async function handler(req: NextApiRequest, res: NextApiResponse) {
  const session = await getServerSession(req, res, authOptions)
  if (session?.user?.isImpersonating) {
    res.status(403).json({ message: 'Forbidden' })
    return
  }
  if (!session?.user?.id) {
    res.status(403).json({ message: 'Forbidden' })
    return
  }

  const subscription = await getSubscription(session.user.id)
  const { hasAccess } = canAccessFeature('autoModerator', subscription)

  if (!hasAccess) {
    res.status(403).json({ message: 'Forbidden' })
    return
  }

  try {
    const { providerAccountId, accessToken, error } = await getTwitchTokens(session.user.id)
    if (error) {
      res.status(403).json({ message: 'Forbidden' })
      return
    }
    const response = await addModerator(providerAccountId, accessToken)
    res.status(200).json(response)
    return
  } catch (error) {
    captureException(error)
    console.error('Failed to update mod:', error)
    res.status(500).json({ error: error.message, message: 'Failed to update mod' })
    return
  }
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const session = await getServerSession(req, res, authOptions)

  if (!session?.user?.id) {
    res.status(403).json({ message: 'Forbidden' })
    return
  }

  if (req.method === 'GET') {
    try {
      // Get all unresolved disable reasons for the user
      const disableReasons = await prisma.disableNotification.findMany({
        orderBy: {
          createdAt: 'desc',
        },
        where: {
          resolvedAt: null,
          userId: session.user.id,
        },
      })

      // Also get settings with disable reasons
      const disabledSettings = await prisma.setting.findMany({
        select: {
          autoDisabledAt: true,
          autoDisabledBy: true,
          disableMetadata: true,
          disableReason: true,
          key: true,
        },
        where: {
          disableReason: {
            not: null,
          },
          userId: session.user.id,
        },
      })

      res.status(200).json({
        disabledSettings,
        notifications: disableReasons,
      })
      return
    } catch (error) {
      captureException(error)
      res.status(500).json({
        error: error instanceof Error ? error.message : 'Unknown error',
        message: 'Failed to get disable reasons',
      })
      return
    }
  }

  res.status(405).json({ message: 'Method Not Allowed' })
}

