function DashboardShell({
  children,
  seo,
}: {
  children: React.ReactElement
  seo?: SEOProps
}) {
  const { status, data } = useSession()
  const router = useRouter()
  // `broken` (set by the Sider breakpoint) is our single "is mobile" signal.
  const [broken, setBroken] = useState(false)
  const [drawerOpen, setDrawerOpen] = useState(false)
  const copyOverlayUrl = useBaseUrl(`overlay/${data?.user?.id ?? ''}`)
  const {
    token: { colorBgLayout },
  } = theme.useToken()
  // Seed selection from the initial route so off-sidebar pages (billing/data/help)
  // don't briefly false-highlight Setup before the route effect runs.
  const [current, setCurrent] = useState(() => findBestMatchingMenuItem(router.pathname).key)
  const [adminOpenKeys, setAdminOpenKeys] = useState<string[]>(() => {
    const { parentKey } = findBestMatchingMenuItem(router.pathname)
    return parentKey ? [parentKey] : []
  })

  // Default SEO values
  const defaultTitle = 'Dashboard | Dotabod'
  const defaultDescription =
    'Manage your Dotabod settings, commands, and features to enhance your Dota 2 streaming experience.'
  const host =
    process.env.NEXT_PUBLIC_VERCEL_PROJECT_PRODUCTION_URL ||
    (typeof window === 'undefined' ? 'dotabod.com' : window.location.host)
  const defaultOgImage = `https://${host}/images/welcome.png`
  const defaultUrl = `https://${host}/dashboard`

  // Use SEO props if provided, otherwise use defaults
  const pageTitle = seo?.title || defaultTitle
  const pageDescription = seo?.description || defaultDescription
  const pageImage = seo?.ogImage || defaultOgImage
  const pageUrl = seo?.canonicalUrl || defaultUrl
  const pageType = seo?.ogType || 'website'
  const { hasAccess: hasAutoModeratorAccess } = useFeatureAccess('autoModerator')

  // Handle Admin accordion open/close
  const onAdminOpenChange: MenuProps['onOpenChange'] = (keys) => {
    setAdminOpenKeys(keys)
  }

  useMaybeSignout()

  useEffect(() => {
    const lastUpdate = localStorage.getItem('lastSingleRunAPI')
    const now = new Date()

    if (!lastUpdate || now.getTime() - Number(lastUpdate) > 24 * 60 * 60 * 1000) {
      localStorage.setItem('lastSingleRunAPI', String(now.getTime()))

      fetch('/api/update-followers').catch((error) => {
        captureException(error)

        console.error(error)
      })
      if (hasAutoModeratorAccess) {
        fetch('/api/make-dotabod-mod').catch((error) => {
          captureException(error)

          console.error(error)
        })
      }
    }
  }, [hasAutoModeratorAccess])

  // Update selected menu item (and open the Admin accordion) when the route changes.
  // Also close the mobile drawer here: tapping a drawer link navigates via the nested
  // <Link>, and relying on Menu.onClick bubbling to close it is unreliable on touch —
  // closing on the route change itself guarantees the new page isn't left hidden behind it.
  useEffect(() => {
    const { pathname } = router
    const { key, parentKey } = findBestMatchingMenuItem(pathname)

    setCurrent(key)
    setDrawerOpen(false)

    if (parentKey && !adminOpenKeys.includes(parentKey)) {
      setAdminOpenKeys((prev) => [...prev, parentKey])
    }
  }, [router.pathname, router.asPath])

  // Close the mobile drawer once we're back on a desktop layout
  useEffect(() => {
    if (!broken) {
      setDrawerOpen(false)
    }
  }, [broken])

  // Fetch notifications from the API (gift toast filters to gift type below)
  const { data: giftNotificationData, mutate: refreshGiftNotifications } = useSWR(
    status === 'authenticated' ? '/api/notifications' : null,
    fetcher,
    SETTINGS_SWR_OPTIONS,
  )

  const [hasGiftNotification, setHasGiftNotification] = useState(false)
  const [giftDetails, setGiftDetails] = useState<{
    id: string
    senderName: string
    giftMessage?: string
    giftType: 'monthly' | 'annual' | 'lifetime'
    giftQuantity?: number
  } | null>(null)
  const [hasLifetime, setHasLifetime] = useState(false)
  const [totalNotifications, setTotalNotifications] = useState(0)

  // Update notification state when data changes
  useEffect(() => {
    // This toast is gift-specific; the notifications endpoint now returns other types
    // too (e.g. new-feature), so consider only unread GIFT_SUBSCRIPTION rows.
    const unreadGifts = (giftNotificationData?.notifications || []).filter(
      (n) => n?.type === 'GIFT_SUBSCRIPTION' && !n?.read,
    )
    const giftNotification = unreadGifts[0]
    if (giftNotification) {
      setGiftDetails({
        giftMessage: giftNotification.giftMessage,
        giftQuantity: giftNotification.giftQuantity || 1,
        giftType: giftNotification.giftType,
        id: giftNotification.id,
        senderName: giftNotification.senderName,
      })
      setHasGiftNotification(true)
    } else {
      setHasGiftNotification(false)
      setGiftDetails(null)
    }

    setHasLifetime(giftNotificationData?.hasLifetime || false)
    // Gift-only count for the toast copy; the endpoint's totalNotifications mixes types.
    setTotalNotifications(unreadGifts.length)
  }, [giftNotificationData])

  const dismissGiftNotification = async () => {
    if (giftDetails?.id) {
      try {
        // Call API to mark notification as read
        const response = await fetch('/api/notifications', {
          body: JSON.stringify({
            notificationId: giftDetails.id,
          }),
          headers: {
            'Content-Type': 'application/json',
          },
          method: 'POST',
        })

        if (!response.ok) {
          const errorData = await response.json()
          console.error('Failed to mark notification as read:', errorData)
          throw new Error(errorData.message || 'Failed to mark notification as read')
        }

        // Refresh notifications after marking as read
        void refreshGiftNotifications()
      } catch (error) {
        console.error('Failed to mark notification as read:', error)
      }
    }
  }

  if (status !== 'authenticated') {
    return null
  }

  const isImpersonating = Boolean(data?.user?.isImpersonating)
  const isAdmin = data?.user?.role === 'admin'
  const navOpts = { isAdmin, isImpersonating }

  // Region item lists, filtered once for the current viewer.
  const primaryItems = filterNav(navConfig.primary, navOpts)
  const bottomItems = filterNav(navConfig.bottom, navOpts)
  const utilityItems = bottomItems.filter((item) => !item.adminOnly)
  const adminItems = bottomItems.filter((item) => item.adminOnly)

  // The flat primary rail + bottom-pinned utilities. Rendered (with full labels) in
  // both the desktop Sider and the mobile Drawer so the two never drift apart.
  const renderNav = ({ onNavigate }: { onNavigate?: () => void }) => {
    const onMenuClick: MenuProps['onClick'] = (e) => {
      setCurrent(e.key)
      onNavigate?.()
    }

    const menuStyle = { background: colorBgLayout, borderInlineEnd: 'none' as const }

    return (
      <nav aria-label='Dashboard' className='flex h-full min-h-0 flex-col overflow-hidden'>
        <div className='shrink-0'>
          <div className='m-auto mb-4 flex h-12 w-full justify-center gap-2 px-4 pt-4'>
            <Link href='/'>
              <DarkLogo className='h-full w-auto' />
            </Link>
          </div>

          <SubscriptionBadge collapsed={false} />

          <div className='flex justify-center py-2'>
            <DisableToggle />
          </div>
        </div>

        <div
          data-testid='dashboard-primary-navigation'
          className='min-h-0 flex-1 overflow-y-auto overscroll-contain'
        >
          <Menu
            onClick={onMenuClick}
            selectedKeys={[current]}
            style={menuStyle}
            mode='inline'
            items={primaryItems.map((item) => navItemToMenuItem(item))}
          />
        </div>

        {(utilityItems.length > 0 || adminItems.length > 0) && (
          <div
            data-testid='dashboard-utility-navigation'
            className='shrink-0 border-t border-gray-700 pt-2 pb-[env(safe-area-inset-bottom)]'
          >
            {utilityItems.length > 0 && (
              <Menu
                onClick={onMenuClick}
                selectedKeys={[current]}
                style={menuStyle}
                mode='inline'
                items={utilityItems.map((item) => navItemToMenuItem(item))}
              />
            )}

            {adminItems.length > 0 && (
              <Menu
                onClick={onMenuClick}
                selectedKeys={[current]}
                openKeys={adminOpenKeys}
                onOpenChange={onAdminOpenChange}
                style={menuStyle}
                mode='inline'
                items={adminItems.map((item) => navItemToMenuItem(item))}
              />
            )}
          </div>
        )}
      </nav>
    )
  }

  return (
    <>
      <Head>
        <title>{pageTitle}</title>
        <meta name='title' content={pageTitle} />
        <meta name='description' content={pageDescription} />
        <meta property='og:type' content={pageType} />
        <meta property='og:url' content={pageUrl} />
        <meta property='og:title' content={pageTitle} />
        <meta property='og:description' content={pageDescription} />
        <meta property='og:image' content={pageImage} />

        <meta property='twitter:card' content='summary_large_image' />
        <meta property='twitter:url' content={pageUrl} />
        <meta property='twitter:title' content={pageTitle} />
        <meta property='twitter:description' content={pageDescription} />
        <meta property='twitter:image' content={pageImage} />

        {seo?.canonicalUrl && <link rel='canonical' href={seo.canonicalUrl} />}

        {/* Dashboard pages should generally not be indexed by search engines */}
        {seo?.noindex && <meta name='robots' content='noindex, nofollow' />}
      </Head>
      <HubSpot />
      <div data-testid='dashboard-viewport' className='h-dvh overflow-hidden bg-gray-800'>
        <Layout className='h-full min-h-0 bg-gray-800'>
          <Sider
            breakpoint='md'
            collapsedWidth={0}
            onBreakpoint={setBroken}
            style={{
              background: colorBgLayout,
            }}
            width={250}
            className='h-dvh shrink-0 overflow-hidden border-r-transparent'
            trigger={null}
            collapsible
            collapsed={broken}
          >
            {/* On mobile the Sider collapses to 0 width; skip its content so it can't
                leak past the zero-width container — the Drawer handles mobile nav. */}
            {!broken && renderNav({})}
          </Sider>

          <Drawer
            placement='left'
            open={drawerOpen}
            onClose={() => {
              setDrawerOpen(false)
            }}
            width={250}
            closable={false}
            rootClassName='md:hidden'
            styles={{
              body: {
                background: colorBgLayout,
                height: '100%',
                overflow: 'hidden',
                padding: 0,
              },
            }}
          >
            {renderNav({
              onNavigate: () => {
                setDrawerOpen(false)
              },
            })}
          </Drawer>

          <Layout className='min-h-0 min-w-0 overflow-hidden bg-gray-800!'>
            <div className='shrink-0'>
              <Banner whatsNewPath='/dashboard/whats-new' />
            </div>

            <Header className='flex h-auto! shrink-0 items-center justify-between gap-3 bg-gray-900! p-4! leading-normal! md:gap-4 md:p-8!'>
              <div className='flex min-w-0 flex-1 items-center gap-2 md:gap-3'>
                <Button
                  type='text'
                  aria-label='Open navigation menu'
                  className='flex shrink-0 items-center md:hidden!'
                  icon={<Bars3Icon className='h-6 w-6 text-gray-200' />}
                  onClick={() => {
                    setDrawerOpen(true)
                  }}
                />
                <div className='w-full max-w-lg min-w-0'>
                  <SettingsSearch />
                </div>
              </div>

              <div className='flex w-fit shrink-0 items-center gap-2 py-1 md:gap-3 md:py-2'>
                <div className='hidden md:block'>
                  <CopyButton value={copyOverlayUrl}>
                    {({ copied, copy }) => (
                      <Button
                        type='dashed'
                        size='small'
                        className={clsx(copied && 'border-green-600! text-green-600!')}
                        onClick={copy}
                      >
                        {copied ? 'Overlay URL copied' : 'Copy Overlay URL'}
                      </Button>
                    )}
                  </CopyButton>
                </div>
                <HelpMenu />
                <UserAccountNav />
              </div>
            </Header>
            {hasGiftNotification && giftDetails && (
              <GiftNotification
                senderName={giftDetails.senderName}
                giftMessage={giftDetails.giftMessage}
                giftType={giftDetails.giftType}
                giftQuantity={giftDetails.giftQuantity}
                onDismiss={dismissGiftNotification}
                hasLifetime={hasLifetime}
                totalNotifications={totalNotifications}
              />
            )}

            <div
              data-testid='dashboard-content-scroll'
              className='min-h-0 flex-1 overflow-y-auto overscroll-contain'
            >
              <div className='flex min-h-full flex-col'>
                <Content className='w-full flex-1 space-y-6 bg-gray-800 p-4 transition-all md:p-8'>
                  {children}
                </Content>
                <footer className='shrink-0 border-t border-gray-700 bg-gray-900 px-4 pt-4 pb-1 text-center text-xs text-gray-400'>
                  <p>
                    Dota 2 and the Dota 2 logo are registered trademarks of Valve Corporation. This
                    site is not affiliated with Valve Corporation.
                  </p>
                </footer>
              </div>
            </div>
          </Layout>
        </Layout>
      </div>
      <CookieConsent />
    </>
  )
}

function WinLossOverlay() {
  const userId = useSession().data?.user?.id
  const {
    data: statsDays,
    loading: statsDaysLoading,
    isSaving: statsDaysSaving,
    updateSetting: updateStatsDays,
  } = useUpdateSetting<number | null>(Settings.wlStatsDays)
  const {
    data: statsStartDate,
    loading: statsStartDateLoading,
    isSaving: statsStartDateSaving,
    updateSetting: updateStatsStartDate,
  } = useUpdateSetting<string | null>(Settings.wlStatsStartDate)
  const [draftStatsDays, setDraftStatsDays] = useState<number | null>(() =>
    typeof statsDays === 'number' && Number.isFinite(statsDays) ? statsDays : null,
  )
  const [draftStatsStartDate, setDraftStatsStartDate] = useState<string | null>(() =>
    typeof statsStartDate === 'string' ? statsStartDate : null,
  )
  const [adjustmentLobbyType, setAdjustmentLobbyType] = useState<0 | 7>(7)
  const [adjustmentAmount, setAdjustmentAmount] = useState<number | null>(1)
  const [adjustmentSaving, setAdjustmentSaving] = useState(false)
  const [adjustmentError, setAdjustmentError] = useState<string | null>(null)
  const {
    error: previewError,
    loading: previewLoading,
    refresh: refreshWinLoss,
    wl,
  } = useWinLoss({
    statsDays: draftStatsDays,
    statsStartDate: draftStatsStartDate,
    userId: statsDaysLoading || statsStartDateLoading ? null : userId,
  })

  useEffect(() => {
    if (typeof statsDays === 'number' && Number.isFinite(statsDays)) {
      setDraftStatsDays(statsDays)
      return
    }

    setDraftStatsDays(null)
  }, [statsDays])

  useEffect(() => {
    setDraftStatsStartDate(typeof statsStartDate === 'string' ? statsStartDate : null)
  }, [statsStartDate])

  const challengeConfigured = draftStatsDays !== null && draftStatsStartDate !== null
  const settingsSaving = statsDaysSaving || statsStartDateSaving

  const saveChallenge = () => {
    if (!challengeConfigured) {
      return
    }
    updateStatsStartDate(draftStatsStartDate)
    updateStatsDays(draftStatsDays)
  }

  const endChallenge = () => {
    setDraftStatsDays(null)
    setDraftStatsStartDate(null)
    updateStatsStartDate(null)
    updateStatsDays(null)
  }

  const validAdjustmentAmount =
    adjustmentAmount !== null &&
    Number.isInteger(adjustmentAmount) &&
    adjustmentAmount >= 1 &&
    adjustmentAmount <= 1000

  const adjustWinLoss = async (won: boolean, direction: -1 | 1) => {
    if (!validAdjustmentAmount) {
      return
    }

    setAdjustmentSaving(true)
    setAdjustmentError(null)

    try {
      const response = await fetch('/api/win-loss-adjustments', {
        body: JSON.stringify({
          delta: direction * adjustmentAmount,
          lobbyType: adjustmentLobbyType,
          won,
        }),
        headers: { 'Content-Type': 'application/json' },
        method: 'POST',
      })
      if (!response.ok) {
        throw new Error(`Win/loss adjustment failed: ${response.status}`)
      }
      refreshWinLoss()
    } catch {
      setAdjustmentError("Couldn't update the record. Try again.")
    } finally {
      setAdjustmentSaving(false)
    }
  }

  const adjustmentTypeLabel = adjustmentLobbyType === 7 ? 'ranked' : 'unranked'
  const adjustmentRecordType = adjustmentLobbyType === 7 ? 'R' : 'U'
  const adjustmentRecord = wl?.records.find((record) => record.type === adjustmentRecordType)
  const canRemoveWin = validAdjustmentAmount && adjustmentAmount <= (adjustmentRecord?.win ?? 0)
  const canRemoveLoss = validAdjustmentAmount && adjustmentAmount <= (adjustmentRecord?.lose ?? 0)

  return (
    <Card title='Win/loss'>
      <div className='subtitle'>
        Show your win/loss record in the overlay and !wl. Turning this off disables both.
      </div>

      <div className='py-4'>
        <TierSwitch settingKey={Settings.commandWL} label='Show win/loss' />
      </div>

      <div className='mb-6 max-w-md'>
        <div className='mb-1 text-sm font-medium'>Challenge window</div>
        <p aria-live='polite' className='mb-3 text-sm text-gray-400'>
          {challengeConfigured
            ? `Counts matches from ${draftStatsStartDate} until ${getChallengeEndDate(draftStatsStartDate, draftStatsDays)}. It ends automatically and returns to per-stream stats.`
            : 'No challenge active. The counter resets when a new stream starts.'}
        </p>
        <Form layout='vertical'>
          <div className='grid gap-3 sm:grid-cols-[minmax(0,1fr)_9rem]'>
            <Form.Item colon={false} label='Challenge start date' className='mb-0'>
              <Input
                aria-label='Challenge start date'
                disabled={statsStartDateLoading || settingsSaving}
                type='date'
                value={draftStatsStartDate ?? ''}
                onChange={(event) => {
                  setDraftStatsStartDate(event.target.value || null)
                }}
              />
            </Form.Item>
            <Form.Item colon={false} label='Duration' className='mb-0'>
              <InputNumber
                aria-label='Challenge duration'
                className='w-full!'
                disabled={statsDaysLoading || settingsSaving}
                max={365}
                min={1}
                placeholder='30 days'
                precision={0}
                value={draftStatsDays}
                onChange={setDraftStatsDays}
              />
            </Form.Item>
          </div>
          <div className='mt-3 flex flex-wrap gap-2'>
            <Button
              disabled={!challengeConfigured || settingsSaving}
              loading={settingsSaving}
              onClick={saveChallenge}
              type='primary'
            >
              Save challenge
            </Button>
            {(statsDays !== null || statsStartDate !== null) && (
              <Button disabled={settingsSaving} onClick={endChallenge}>
                End challenge
              </Button>
            )}
          </div>
        </Form>
        <p className='mt-2 text-xs text-gray-500'>
          Choose 1–365 days. !today still reports today only.
        </p>
      </div>

      <fieldset className='max-w-md border-0 p-0'>
        <legend className='mb-1 text-sm font-medium'>Manual corrections</legend>
        <p className='mb-3 text-sm text-gray-400'>
          Add games played off stream or correct a missed result. Dotabod stores only this
          correction, not your offline match history. It follows the active challenge or per-stream
          counter.
        </p>
        <Radio.Group
          aria-label='Correction match type'
          disabled={adjustmentSaving}
          onChange={(event) => {
            setAdjustmentLobbyType(event.target.value as 0 | 7)
          }}
          value={adjustmentLobbyType}
        >
          <Radio.Button value={7}>Ranked</Radio.Button>
          <Radio.Button value={0}>Unranked</Radio.Button>
        </Radio.Group>
        <div className='mt-3 flex flex-wrap items-end gap-3'>
          <div>
            <label className='mb-1 block text-xs font-medium text-gray-400' htmlFor='wl-adjustment'>
              Correction amount
            </label>
            <InputNumber
              aria-label='Correction amount'
              className='w-32!'
              disabled={adjustmentSaving}
              id='wl-adjustment'
              max={1000}
              min={1}
              precision={0}
              value={adjustmentAmount}
              onChange={setAdjustmentAmount}
            />
          </div>
          <span className='pb-1 text-xs text-gray-400'>Totals cannot go below zero.</span>
        </div>
        <div className='mt-3 flex flex-wrap gap-2'>
          <Button
            aria-label={`Add ${adjustmentTypeLabel} win`}
            disabled={adjustmentSaving || !validAdjustmentAmount}
            onClick={() => void adjustWinLoss(true, 1)}
          >
            + Win
          </Button>
          <Button
            aria-label={`Remove ${adjustmentTypeLabel} win`}
            disabled={adjustmentSaving || !canRemoveWin}
            onClick={() => void adjustWinLoss(true, -1)}
          >
            − Win
          </Button>
          <Button
            aria-label={`Add ${adjustmentTypeLabel} loss`}
            disabled={adjustmentSaving || !validAdjustmentAmount}
            onClick={() => void adjustWinLoss(false, 1)}
          >
            + Loss
          </Button>
          <Button
            aria-label={`Remove ${adjustmentTypeLabel} loss`}
            disabled={adjustmentSaving || !canRemoveLoss}
            onClick={() => void adjustWinLoss(false, -1)}
          >
            − Loss
          </Button>
        </div>
        {adjustmentError ? (
          <p aria-live='polite' className='mt-2 text-sm text-red-400'>
            {adjustmentError}
          </p>
        ) : null}
      </fieldset>

      <div className='my-6 flex min-h-12 flex-col items-center justify-center gap-2'>
        <span className='text-xs font-medium text-gray-500'>Your record</span>
        {previewLoading || !wl ? (
          <Skeleton.Input active size='small' style={{ height: 34, width: 132 }} />
        ) : (
          <WinLossCard wl={wl} />
        )}
        {previewError && <span className='text-xs text-gray-400'>Preview unavailable</span>}
      </div>
    </Card>
  )
}

async function readSecrets(sql: ReturnType<typeof postgres>) {
  const rows = (await sql`
    select name, decrypted_secret from vault.decrypted_secrets
    where name in (${VAULT_TOKEN_NAME}, ${VAULT_SYNC_SECRET_NAME})
  `) as unknown as { name: string; decrypted_secret: string }[]
  const map = new Map(rows.map((r) => [r.name, r.decrypted_secret]))
  return {
    syncSecret: map.get(VAULT_SYNC_SECRET_NAME) ?? '',
    token: map.get(VAULT_TOKEN_NAME) ?? '',
  }
}

async function handleCryptoInvoiceEvent(
  invoice: Stripe.Invoice,
  tx: Prisma.TransactionClient,
): Promise<boolean> {
  const customerId = invoice.customer as string
  const resolvedUser = await resolveUserIdForCryptoInvoice(invoice, tx)
  const userId = resolvedUser?.userId ?? null

  if (resolvedUser) {
    console.log(
      JSON.stringify({
        customerId,
        event: 'crypto_user_resolution',
        invoiceId: invoice.id,
        source: resolvedUser.source,
        userId,
      }),
    )
  }

  if (!userId) {
    console.error(`Missing userId in crypto invoice metadata: ${invoice.id}`)
    return false
  }

  return (
    (await withErrorHandling(
      async () => {
        // Find the subscription that references this invoice
        const subscription = await tx.subscription.findFirst({
          where: {
            metadata: {
              equals: invoice.id,
              path: ['renewalInvoiceId'],
            },
            stripeCustomerId: customerId,
          },
        })

        if (!subscription) {
          console.log(`No subscription found with renewalInvoiceId: ${invoice.id}`)
          // If we have an overdue or uncollectible invoice but no subscription with this invoice ID,
          // Try to find by customer ID (for current period invoices)
          if (
            invoice.status === 'uncollectible' ||
            invoice.status === 'void' ||
            (invoice.status === 'open' &&
              invoice.due_date &&
              new Date(invoice.due_date * 1000) < new Date())
          ) {
            const activeSubscription = await tx.subscription.findFirst({
              where: {
                status: { in: [SubscriptionStatus.ACTIVE, SubscriptionStatus.PAST_DUE] },
                stripeCustomerId: customerId,
                userId,
              },
            })

            if (activeSubscription) {
              console.log(
                `Found active subscription ${activeSubscription.id} for customer ${customerId}`,
              )
              // Mark as past due or cancelled depending on the situation
              const newStatus =
                invoice.status === 'uncollectible' || invoice.status === 'void'
                  ? SubscriptionStatus.CANCELED
                  : SubscriptionStatus.PAST_DUE

              await tx.subscription.update({
                data: {
                  metadata: {
                    ...toMetadataObject(activeSubscription.metadata),
                    lastInvoiceStatus: invoice.status,
                    lastUnpaidInvoiceId: invoice.id,
                  },
                  status: newStatus,
                  updatedAt: new Date(),
                },
                where: { id: activeSubscription.id },
              })

              console.log(`Updated subscription ${activeSubscription.id} status to ${newStatus}`)
              return true
            }
          }

          return false
        }

        // Only process paid invoices
        if (invoice.status === 'paid') {
          console.log(
            `Processing paid crypto invoice ${invoice.id} for subscription ${subscription.id}`,
          )

          // Check if this is a lifetime subscription - lifetime subscriptions should never generate renewal invoices
          if (subscription.transactionType === 'LIFETIME') {
            console.log(
              `Skipping renewal invoice creation for lifetime subscription ${subscription.id}`,
            )
            return true
          }

          // Get price ID and period from the subscription
          const priceId = subscription.stripePriceId
          // Extract and use metadata safely
          const metadata = (subscription.metadata as Record<string, unknown>) || {}
          const pricePeriod = (metadata.priceType as string) || 'monthly'

          if (!priceId) {
            console.error(`Missing priceId in subscription: ${subscription.id}`)
            return false
          }

          // Calculate the new period end date
          const isAnnual = pricePeriod === 'annual'

          // Handle the Date properly, considering currentPeriodEnd could be a Date object or string
          let baseDate: Date
          if (subscription.currentPeriodEnd) {
            // Handle if it's already a Date or needs to be converted from string
            baseDate =
              subscription.currentPeriodEnd instanceof Date
                ? subscription.currentPeriodEnd
                : new Date(subscription.currentPeriodEnd)
          } else {
            baseDate = new Date()
          }

          const newPeriodEnd = new Date(baseDate)

          if (isAnnual) {
            newPeriodEnd.setFullYear(newPeriodEnd.getFullYear() + 1)
          } else {
            // Monthly
            newPeriodEnd.setMonth(newPeriodEnd.getMonth() + 1)
          }

          // Create a new draft invoice for the next period
          const renewalDate = new Date(newPeriodEnd)
          // Set the invoice date to 7 days before the period ends
          renewalDate.setDate(renewalDate.getDate() - 7)

          // Calculate the period end date based on the price period
          const periodEnd = new Date()
          if (isAnnual) {
            periodEnd.setFullYear(periodEnd.getFullYear() + 1)
          } else {
            // Monthly
            periodEnd.setMonth(periodEnd.getMonth() + 1)
          }

          try {
            // Create a new draft invoice for the next period
            // Use type assertion to fix customerId type issue
            const params: Stripe.InvoiceCreateParams = {
              auto_advance: true, // Enable automatic advancement so Stripe handles finalization
              automatically_finalizes_at: Math.floor(renewalDate.getTime() / 1000),
              collection_method: 'send_invoice',
              customer: customerId,
              description: `Crypto Dotabod Pro ${pricePeriod.charAt(0).toUpperCase() + pricePeriod.slice(1)} subscription`,
              due_date: Math.floor((renewalDate.getTime() + 7 * 24 * 60 * 60 * 1000) / 1000), // Due date 7 days after finalization date
              metadata: {
                isCryptoPayment: 'true',
                isRenewalInvoice: 'true',
                previousInvoiceId: invoice.id ?? '',
                pricePeriod,
                userId,
              },
            }

            const newInvoice = await stripe.invoices.create(params)

            // Fetch the price details from Stripe
            const price = await stripe.prices.retrieve(priceId)
            if (!price.unit_amount) {
              throw new Error('Price unit amount is not set')
            }

            // Add the line item for the price
            await stripe.invoiceItems.create({
              amount: price.unit_amount,
              customer: customerId,
              description: `Crypto Dotabod Pro ${pricePeriod.charAt(0).toUpperCase() + pricePeriod.slice(1)} subscription`,
              invoice: newInvoice.id,
            })

            console.log(
              `Created new renewal draft invoice ${newInvoice.id} for next crypto payment period`,
            )

            // Update the subscription with the new period end and invoice ID
            await tx.subscription.update({
              data: {
                cancelAtPeriodEnd: true, // Will expire at the end of the period
                currentPeriodEnd: newPeriodEnd,
                metadata: {
                  ...toMetadataObject(subscription.metadata),
                  previousRenewalInvoiceId: invoice.id ?? '',
                  priceType: pricePeriod,
                  renewalDueDate: renewalDate.toISOString(),
                  renewalInvoiceId: newInvoice.id,
                },
                status: SubscriptionStatus.ACTIVE,
                updatedAt: new Date(),
              },
              where: { id: subscription.id },
            })

            console.log(
              `Updated crypto subscription ${subscription.id} with new period end ${newPeriodEnd.toISOString()} and new invoice ID ${newInvoice.id}`,
            )

            return true
          } catch (error) {
            console.error('Failed to create next crypto renewal invoice:', error)

            // Still update the subscription period
            await tx.subscription.update({
              data: {
                cancelAtPeriodEnd: true,
                currentPeriodEnd: newPeriodEnd,
                metadata: {
                  ...toMetadataObject(subscription.metadata),
                  renewalError: 'true',
                },
                status: SubscriptionStatus.ACTIVE,
                updatedAt: new Date(),
              },
              where: { id: subscription.id },
            })

            return false
          }
        } else if (invoice.status === 'uncollectible' || invoice.status === 'void') {
          // Mark the subscription as inactive if the invoice is void or uncollectible
          await tx.subscription.update({
            data: {
              metadata: {
                ...toMetadataObject(subscription.metadata),
                cancellationReason: 'invoice_uncollectible',
                lastUnpaidInvoiceId: invoice.id,
              },
              status: SubscriptionStatus.CANCELED,
              updatedAt: new Date(),
            },
            where: { id: subscription.id },
          })

          console.log(
            `Marked subscription ${subscription.id} as CANCELED due to uncollectible/void invoice`,
          )
          return true
        } else if (
          invoice.status === 'open' &&
          invoice.due_date &&
          new Date(invoice.due_date * 1000) < new Date()
        ) {
          // Invoice is overdue (open but past due date)
          await tx.subscription.update({
            data: {
              metadata: {
                ...toMetadataObject(subscription.metadata),
                lastOverdueInvoiceId: invoice.id,
              },
              status: SubscriptionStatus.PAST_DUE,
              updatedAt: new Date(),
            },
            where: { id: subscription.id },
          })

          console.log(`Marked subscription ${subscription.id} as PAST_DUE due to overdue invoice`)
          return true
        }

        return true
      },
      `handleCryptoInvoiceEvent(${invoice.id})`,
      customerId,
    )) !== null
  )
}

