function getValueOrDefault(
  key: SettingKeys | ChatterSettingKeys | undefined,
  settings?: Setting[],
): unknown {
  if (!key) {
    return undefined
  }

  // Handle chatter settings
  if (key.startsWith('chatters.')) {
    const chattersData = settings?.find((s) => s.key === 'chatters') as
      | {
          value?: Partial<Record<keyof ChattersSettings, { enabled?: boolean }>>
        }
      | undefined
    const chatterKey = key.split('.')[1] as keyof ChattersSettings
    return (
      chattersData?.value?.[chatterKey]?.enabled ?? defaultSettings.chatters[chatterKey].enabled
    )
  }

  // Handle regular settings
  const setting = settings?.find((s) => s.key === key)
  return setting?.value ?? defaultSettings[key as keyof typeof defaultSettings]
}

[...items].sort((a, b) => {
    const byRarity = rarityRank(b) - rarityRank(a)
    if (byRarity) {
      return byRarity
    }
    const ai = SLOT_ORDER.indexOf(a.slot)
    const bi = SLOT_ORDER.indexOf(b.slot)
    const bySlot = (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi)
    if (bySlot) {
      return bySlot
    }
    return a.name.localeCompare(b.name)
  })

function getPlanLabel(
  tier?: SubscriptionTier | null,
  stripePriceId?: string | null,
  transactionType?: string | null,
): string {
  if (transactionType === TransactionType.LIFETIME) {
    return 'Pro Lifetime'
  }

  if (!tier || tier === SubscriptionTier.FREE) {
    return 'Free'
  }

  const period = getCurrentPeriod(stripePriceId)
  const prettyPeriod = period.charAt(0).toUpperCase() + period.slice(1)
  return `${tier.charAt(0)}${tier.slice(1).toLowerCase()} ${prettyPeriod}`
}

