    const page = await prisma.user.findMany({
      orderBy: { id: 'asc' },
      select: { displayName: true, email: true, id: true },
      take,
      where: { email: { not: null }, ...(lastId ? { id: { gt: lastId } } : {}) },
    })
    if (page.length === 0) {
      break
    }

    await runPool(page)
    processed += page.length
    lastId = page.at(-1).id
