  }

  console.log(`✅ Done. Synced ${synced}, failed ${failed}, total processed ${processed}.`)
}

function periodStart(period: MatchPeriod): Date | null {
  if (period === 'all') {
    return null
  }
  const days = period === '7d' ? 7 : 30
  return new Date(Date.now() - days * 24 * 60 * 60 * 1000)
}

