function TierSlider({
  settingKey,
  label,
  className,
  hideTierBadge,
  disabled: externalDisabled,
  value: externalValue,
  onChange: externalOnChange,
  helpText,
  debounceMs = 500, // Default debounce of 500ms
  ...sliderProps
}: TierSliderProps) {
  const { data: rawValue, updateSetting, tierAccess } = useUpdateSetting<number>(settingKey)
  const [localValue, setLocalValue] = useState<number>(externalValue ?? rawValue ?? 0)
  const [debounceTimeout, setDebounceTimeout] = useState<NodeJS.Timeout | null>(null)

  const isDisabled = externalDisabled || !tierAccess.hasAccess

  // Update local value when external value changes
  useEffect(() => {
    if (externalValue !== undefined) {
      setLocalValue(externalValue)
    } else if (rawValue !== undefined) {
      setLocalValue(rawValue)
    }
  }, [externalValue, rawValue])

  const handleChange = (value: number) => {
    setLocalValue(value)

    // If external onChange is provided, call it immediately
    if (externalOnChange) {
      externalOnChange(value)
    } else {
      // Otherwise debounce the updateSetting call
      if (debounceTimeout) {
        clearTimeout(debounceTimeout)
      }

      const newTimeout = setTimeout(() => {
        updateSetting(value)
      }, debounceMs)

      setDebounceTimeout(newTimeout)
    }
  }

  // Clean up timeout on unmount
  useEffect(
    () => () => {
      if (debounceTimeout) {
        clearTimeout(debounceTimeout)
      }
    },
    [debounceTimeout],
  )

  const sliderId = `slider-${settingKey}`

  return (
    <div className={`space-y-1 ${className ?? ''}`}>
      {label && (
        <div className='flex items-center'>
          <label htmlFor={sliderId} className='block text-sm'>
            {label}
          </label>
          {!tierAccess.hasAccess && !hideTierBadge && (
            <span className='ml-2'>
              <TierBadge requiredTier={tierAccess.requiredTier} />
            </span>
          )}
        </div>
      )}
      <div className='py-2'>
        <Slider
          id={sliderId}
          value={localValue}
          onChange={handleChange}
          disabled={isDisabled}
          {...sliderProps}
        />
      </div>
      {helpText && <span className='block text-xs italic'>{helpText}</span>}
    </div>
  )
}

useCallback(
    async (notificationId: string) => {
      try {
        const response = await fetch('/api/settings/acknowledge-disable', {
          body: JSON.stringify({ notificationId }),
          headers: {
            'Content-Type': 'application/json',
          },
          method: 'POST',
        })

        if (!response.ok) {
          throw new Error('Failed to acknowledge disable reason')
        }

        // Optimistically update the data
        if (data) {
          void mutate(
            {
              ...data,
              notifications: data.notifications.map((notification) =>
                notification.id === notificationId
                  ? { ...notification, acknowledged: true }
                  : notification,
              ),
            },
            false,
          )
        }

        return true
      } catch (error) {
        console.error('Failed to acknowledge disable reason:', error)
        return false
      }
    },
    [data, mutate],
  )

function noteFor(method: PaymentMethod, period: PricePeriod): string {
  const isLifetime = period === 'lifetime'
  switch (method) {
    case 'paypal': {
      return isLifetime
        ? 'One-time payment through your PayPal account.'
        : 'Renews automatically through your PayPal account.'
    }
    case 'crypto': {
      return isLifetime
        ? 'One-time payment in BTC, USDT, ETH, and 100+ other coins.'
        : "You'll get an invoice each period to pay in BTC, USDT, ETH, and 100+ other coins."
    }
    default: {
      return isLifetime ? 'One-time card payment.' : 'Renews automatically. Cancel anytime.'
    }
  }
}

