async function createJob(matchId: string): Promise<number> {
  // Check if we already have a job request in progress for this match
  if (jobRequestCache.has(matchId)) {
    console.log(`[MMR] Using existing job request for matchId: ${matchId}`)
    const cachedJob = jobRequestCache.get(matchId)
    if (!cachedJob) {
      throw new Error(`Job request for match ${matchId} was in cache but returned undefined`)
    }
    return await cachedJob
  }

  // Set up the retry operation
  const operation = retry.operation({
    factor: 3, // Exponential backoff factor
    maxTimeout: 60 * 1000, // Maximum retry timeout (60 seconds)
    minTimeout: 1 * 1000, // Minimum retry timeout (1 second)
    retries: 8, // Number of retries
  })

  const jobPromise = new Promise<number>((resolve, reject) => {
    operation.attempt(async () => {
      try {
        const createdJob = await axios.post(`https://api.opendota.com/api/request/${matchId}`)

        const jobId = createdJob.data?.job?.jobId
        if (typeof jobId !== 'number') {
          if (operation.retry(new Error('Match not ready to be parsed'))) {
            return
          }

          // Remove from cache if failed
          jobRequestCache.delete(matchId)
          reject(new Error('Match not ready to be parsed'))
          return
        }

        // Continue once parsing is complete
        resolve(jobId)
      } catch (error) {
        // All this because opendota responds with e400 if not ready
        if (operation.retry(new Error('Match not ready to be parsed'))) {
          return
        }

        // Remove from cache if failed
        jobRequestCache.delete(matchId)
        reject(error)
      }
    })
  })

  // Store the promise in the cache
  jobRequestCache.set(matchId, jobPromise)

  // Clean up cache after promise resolves or rejects
  void jobPromise.finally(() => {
    // Keep successful results in cache for a while, but eventually clean them up
    setTimeout(
      () => {
        jobRequestCache.delete(matchId)
      },
      5 * 60 * 1000,
    ) // 5 minutes
  })

  return await jobPromise
}

function calculateGiftEndDate(
  giftType: string,
  quantity: number,
  startDate: Date = new Date(),
): Date {
  // Create a new date for safer manipulation
  const endDate = new Date(startDate)
  const originalDay = startDate.getUTCDate()

  // Lifetime subscription (add 100 years)
  if (giftType === 'lifetime') {
    endDate.setUTCFullYear(endDate.getUTCFullYear() + 100)
    return endDate
  }

  // Annual subscription (add years)
  if (giftType === 'annual') {
    endDate.setUTCFullYear(endDate.getUTCFullYear() + quantity)
    return endDate
  }

  // For monthly subscriptions, use a safer approach to add months
  // Calculate target month and year
  const totalMonths = startDate.getUTCMonth() + quantity
  const targetMonth = totalMonths % 12
  const yearsToAdd = Math.floor(totalMonths / 12)

  // Set to 1st of month first to avoid month skipping issues
  endDate.setUTCDate(1)
  endDate.setUTCMonth(targetMonth)
  endDate.setUTCFullYear(startDate.getUTCFullYear() + yearsToAdd)

  // Get the last day of the target month
  const lastDayOfMonth = new Date(
    Date.UTC(endDate.getUTCFullYear(), endDate.getUTCMonth() + 1, 0),
  ).getUTCDate()

  // Set to either original day or last day of month, whichever is smaller
  const finalDay = Math.min(originalDay, lastDayOfMonth)
  endDate.setUTCDate(finalDay)

  return endDate
}

