async function addModerator(broadcasterId: string | undefined, accessToken: string) {
  if (!broadcasterId) {
    throw new Error('Broadcaster ID is required')
  }

  const checkUrl = `https://api.twitch.tv/helix/moderation/moderators?broadcaster_id=${broadcasterId}&user_id=${process.env.TWITCH_BOT_PROVIDERID}`
  const headers = {
    Authorization: `Bearer ${accessToken}`,
    'Client-Id': process.env.TWITCH_CLIENT_ID ?? '',
  }

  try {
    // Check if the user is already a moderator
    const checkResponse = await fetch(checkUrl, { headers, method: 'GET' })
    if (!checkResponse.ok) {
      throw new Error(`Failed to get moderators: ${checkResponse.statusText}`)
    }
    const checkData = await checkResponse.json()
    if (checkData.data && checkData.data.length > 0) {
      // The user is already a moderator
      return { message: 'User is already a moderator', status: 'OK' }
    }

    // If the user is not a moderator, add them as a moderator
    const url = `https://api.twitch.tv/helix/moderation/moderators?broadcaster_id=${broadcasterId}&user_id=${process.env.TWITCH_BOT_PROVIDERID}`
    const response = await fetch(url, { headers, method: 'POST' })
    if (!response.ok) {
      throw new Error(`Failed to add moderator: ${response.statusText}`)
    }
    if (response.status === 204) {
      return { message: 'Added Dotabod as moderator', status: 'OK' }
    }
  } catch (error) {
    captureException(error)
    console.error(error)
    return { error: error.message, message: 'Error', status: 'ERROR' } // Handle error gracefully
  }
}

async function completeLifetimeOrder(
  order: PayPalOrder,
  capture: PayPalCaptureResult,
): Promise<void> {
  const metadata = (order.metadata as Record<string, unknown>) || {}
  const stripePriceId = (metadata.stripePriceId as string) || null

  await prisma.$transaction(async (tx) => {
    // Skip if the user already has an active lifetime purchase (idempotency).
    const existingLifetime = await tx.subscription.findFirst({
      select: { id: true },
      where: {
        status: SubscriptionStatus.ACTIVE,
        transactionType: TransactionType.LIFETIME,
        userId: order.userId,
      },
    })

    if (!existingLifetime) {
      const farFuture = new Date()
      farFuture.setFullYear(farFuture.getFullYear() + 100)
      await tx.subscription.create({
        data: {
          cancelAtPeriodEnd: false,
          currentPeriodEnd: farFuture,
          metadata: {
            paymentProvider: 'paypal',
            paypalCaptureId: capture.captureId ?? '',
            paypalOrderId: order.paypalOrderId,
          },
          status: SubscriptionStatus.ACTIVE,
          stripePriceId: stripePriceId || undefined,
          tier: 'PRO',
          transactionType: TransactionType.LIFETIME,
          userId: order.userId,
        },
      })
    }

    await tx.payPalOrder.update({
      data: {
        captureId: capture.captureId ?? undefined,
        lastWebhookAt: new Date(),
        metadata: { ...metadata, processedSuccessfully: true },
        payerId: capture.payerId ?? undefined,
        status: capture.status,
      },
      where: { paypalOrderId: order.paypalOrderId },
    })
  })
}

