async function isModerator(broadcasterId: string, accessToken: string): Promise<boolean> {
  const botProviderId = process.env.TWITCH_BOT_PROVIDERID
  if (!botProviderId) {
    throw new Error('TWITCH_BOT_PROVIDERID is not set')
  }

  const url = `https://api.twitch.tv/helix/moderation/moderators?broadcaster_id=${broadcasterId}&user_id=${botProviderId}`
  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Client-Id': process.env.TWITCH_CLIENT_ID ?? '',
    },
    method: 'GET',
  })

  if (!response.ok) {
    throw new HelixStatusError(response.status)
  }
  const body = (await response.json()) as { data?: unknown[] }
  return Array.isArray(body.data) && body.data.length > 0
}

async function ensureCustomer(
  user: {
    id: string
    email?: string | null
    name?: string | null
    image?: string | null
    locale?: string | null
    twitchId?: string | null
  },
  tx: Prisma.TransactionClient,
): Promise<string> {
  // Look for any existing subscription to get a customer ID
  const subscription = await tx.subscription.findFirst({
    orderBy: { createdAt: 'desc' }, // Use the most recent subscription
    select: { stripeCustomerId: true },
    where: { userId: user.id },
  })

  let customerId = subscription?.stripeCustomerId

  // Verify existing customer
  if (customerId) {
    try {
      await stripe.customers.retrieve(customerId)
    } catch (error) {
      console.error('Invalid customer ID found:', error)
      customerId = null
    }
  }

  // Create or find customer if needed (email is optional)
  if (!customerId) {
    if (user.email) {
      const existingCustomers = await stripe.customers.list({
        email: user.email,
        limit: 1,
      })

      if (existingCustomers.data.length > 0) {
        customerId = existingCustomers.data[0].id
      }
    }

    if (!customerId) {
      const newCustomer = await createStripeCustomer(user)
      customerId = newCustomer.id
    }

    if (!subscription?.stripeCustomerId) {
      // Update existing subscriptions with no customer ID
      await tx.subscription.updateMany({
        data: { stripeCustomerId: customerId, updatedAt: new Date() },
        where: { stripeCustomerId: null, userId: user.id },
      })
    }
  }

  if (!customerId) {
    throw new Error('Unable to establish customer ID')
  }

  return customerId
}

function InstallPage() {
  const track = useTrack()
  const [activeKey, setActiveKey] = useState('windows')
  const [autoRoutedToManual, setAutoRoutedToManual] = useState(false)
  const router = useRouter()

  const updateUrlWithGsiType = (newGsiType: 'windows' | 'manual') => {
    // Update the URL without adding a new history entry
    void router.replace(
      {
        pathname: router.pathname,
        query: { ...router.query, gsiType: newGsiType },
      },
      undefined,
      { shallow: true },
    ) // `shallow: true` to not trigger data fetching methods again
  }

  useEffect(() => {
    const parsedStep = router.query.gsiType
    if (parsedStep === 'windows' || parsedStep === 'manual') {
      setActiveKey(parsedStep)
    }
  }, [router.query.gsiType])

  useEffect(() => {
    if (!router.isReady || router.query.gsiType) {
      return
    }

    const platform =
      // @ts-expect-error userAgentData is not yet in the TS types
      navigator.userAgentData?.platform?.toLowerCase() ?? navigator.userAgent.toLowerCase()

    if (platform.includes('win')) {
      updateUrlWithGsiType('windows')
    } else {
      updateUrlWithGsiType('manual')
      setAutoRoutedToManual(true)
    }
    // UpdateUrlWithGsiType is stable enough; depending on router.isReady ensures
    // We only auto-route after Next.js has hydrated the query.
  }, [router.isReady, router.query.gsiType])

  return (
    <Card>
      {autoRoutedToManual && activeKey === 'manual' && (
        <Alert
          type='info'
          showIcon
          className='mb-4 max-w-2xl'
          message='Showing manual install for your operating system'
          description={
            <span>
              The Automatic installer is Windows only. If you play Dota 2 on Windows,{' '}
              <Button
                type='link'
                onClick={() => {
                  updateUrlWithGsiType('windows')
                }}
                className='h-auto! p-0! align-baseline!'
              >
                switch to the Automatic tab
              </Button>{' '}
              for a one-line install. Both options are free.
            </span>
          }
        />
      )}
      <Tabs
        onTabClick={(key) => {
          track('install_type/click', { label: key })
        }}
        destroyInactiveTabPane
        defaultActiveKey={activeKey}
        activeKey={activeKey}
        onChange={(key) => {
          if (key === 'windows' || key === 'manual') {
            updateUrlWithGsiType(key)
          }
        }}
        items={[
          {
            children: <WindowsInstaller />,
            icon: <WindowsOutlined />,
            key: 'windows',
            label: 'Automatic (Windows)',
          },
          {
            children: <UnixInstaller />,
            icon: (
              <>
                <AppleOutlined />
                <LinuxOutlined />
              </>
            ),
            key: 'manual',
            label: 'Manual (Mac, Linux, or Windows fallback)',
          },
        ]}
      />
    </Card>
  )
}

