          isKeyboardNavigationRef.current = false
        }, 100)
        break
      }
      case 'Enter': {
        e.preventDefault()
        if (orderedResults[selectedIndex]) {
          navigateToSetting(orderedResults[selectedIndex])
        }
        break
      }
      case 'Escape': {
        e.preventDefault()
        setIsOpen(false)
        searchInputRef.current?.blur()
        break
      }
    }

