async function fetchHelixUser(accessToken: string): Promise<HelixUser | null> {
  try {
    const res = await fetch('https://api.twitch.tv/helix/users', {
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Client-Id': process.env.TWITCH_CLIENT_ID ?? '',
      },
    })
    if (!res.ok) {
      noteFallback('helix_non_ok', { status: res.status })
      return null
    }
    const body = (await res.json()) as { data?: HelixUser[] }
    const user = body.data?.[0]
    if (!user) {
      noteFallback('helix_empty_data')
      return null
    }
    return user
  } catch (error) {
    noteFallback('fetch_throw', {
      error: error instanceof Error ? error.message : String(error),
    })
    return null
  }
}

function contrastRatio(foreground: string, background: string, canvas?: string) {
  let foregroundColor = parseColor(foreground)
  let backgroundColor = parseColor(background)
  const canvasColor = parseColor(canvas ?? 'var(--color-gray-900)')

  if (backgroundColor[3] < 1) {
    backgroundColor = composite(backgroundColor, canvasColor)
  }
  if (foregroundColor[3] < 1) {
    foregroundColor = composite(foregroundColor, backgroundColor)
  }

  const foregroundLuminance = relativeLuminance(foregroundColor)
  const backgroundLuminance = relativeLuminance(backgroundColor)

  return (
    (Math.max(foregroundLuminance, backgroundLuminance) + 0.05) /
    (Math.min(foregroundLuminance, backgroundLuminance) + 0.05)
  )
}

