async function createLifetimePurchase(
  userId: string,
  customerId: string,
  priceId: string | null,
  tx: Prisma.TransactionClient,
  metadata?: Prisma.InputJsonObject,
): Promise<{ id: string }> {
  const existingLifetimePurchase = await tx.subscription.findFirst({
    select: {
      id: true,
    },
    where: {
      status: SubscriptionStatus.ACTIVE,
      transactionType: TransactionType.LIFETIME,
      userId,
    },
  })

  if (existingLifetimePurchase) {
    console.log(
      `Skipping duplicate lifetime purchase for user ${userId}; active lifetime subscription ${existingLifetimePurchase.id} already exists`,
    )
    return existingLifetimePurchase
  }

  // Lifetime subscriptions don't expire for 100 years
  const farFutureDate = new Date()
  farFutureDate.setFullYear(farFutureDate.getFullYear() + 100)

  console.log(
    `Creating lifetime purchase for user ${userId} with price ID ${priceId} in createLifetimePurchase`,
  )

  return await tx.subscription.create({
    data: {
      cancelAtPeriodEnd: false,
      currentPeriodEnd: farFutureDate,
      status: SubscriptionStatus.ACTIVE,
      stripeCustomerId: customerId,
      stripePriceId: priceId || undefined,
      tier: 'PRO',
      transactionType: TransactionType.LIFETIME,
      userId,
      ...(metadata ? { metadata } : {}),
    },
    select: {
      id: true,
    },
  })
}

function buildMatchHistorySummary(groups: MatchResultGroup[]): {
  heroesPlayed: number
  losses: number
  matches: number
  winRate: number
  wins: number
} {
  let wins = 0
  let losses = 0
  const heroes = new Set<string>()

  for (const group of groups) {
    if (group.won === true) {
      wins += group.count
    }
    if (group.won === false) {
      losses += group.count
    }
    if (group.heroName) {
      heroes.add(group.heroName)
    }
  }

  const matches = wins + losses
  return {
    heroesPlayed: heroes.size,
    losses,
    matches,
    winRate: percentage(wins, matches),
    wins,
  }
}

