    console.log()
    console.log('  # Actual fix:')
    console.log(
      `  doppler run -- pnpm dlx tsx scripts/fix-opennode-payment.ts ${charge.stripeInvoiceId}`,
    )
    console.log()
  }

  console.log('='.repeat(80))
  console.log()
}

