function sortByRarity(items: CosmeticItem[]): CosmeticItem[] {
  return [...items].sort((a, b) => {
    const byRarity = rarityRank(b) - rarityRank(a)
    if (byRarity) {
      return byRarity
    }
    const ai = SLOT_ORDER.indexOf(a.slot)
    const bi = SLOT_ORDER.indexOf(b.slot)
    const bySlot = (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi)
    if (bySlot) {
      return bySlot
    }
    return a.name.localeCompare(b.name)
  })
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const authHeader = req.headers?.authorization
  if (
    process.env.NODE_ENV !== 'development' &&
    process.env.VERCEL_ENV !== 'development' &&
    (!process.env.CRON_SECRET || authHeader !== `Bearer ${process.env.CRON_SECRET}`)
  ) {
    res.status(401).json({ success: false })
    return
  }

  if (req.method !== 'GET') {
    console.log('Invalid method:', req.method)
    res.status(405).json({ message: 'Method not allowed' })
    return
  }

  const twitchId = process.env.CRON_TWITCH_ID

  if (!twitchId) {
    console.log('No Twitch ID found')
    res.status(403).json({ message: 'Forbidden' })
    return
  }

  const authToken = process.env.SEVENTV_AUTH
  if (!authToken) {
    console.log('No 7TV auth token found')
    res.status(500).json({ message: 'Server configuration error' })
    return
  }

  const client = create7TVClient(authToken)
  let userId = 'N/A'
  let activeEmoteSetId = 'N/A'
  let addedTestEmote = false

  try {
    const stvResponse = await get7TVUser(twitchId)
    userId = stvResponse.user?.id ?? ''
    activeEmoteSetId = stvResponse.emote_set?.id || 'N/A'

    if (!stvResponse.emote_set?.id) {
      throw new Error('No active 7TV emote set found')
    }

    console.log('Removing stale test emote if needed...')
    await removeTestEmoteIfPresent(client, stvResponse.emote_set.id)

    console.log('Adding test emote to active emote set...')
    await client.request(CHANGE_EMOTE_IN_SET, {
      action: 'ADD',
      emote_id: TEST_EMOTE_ID,
      id: stvResponse.emote_set.id,
      name: TEST_EMOTE_NAME,
    })
    addedTestEmote = true

    console.log('Verifying test emote addition...')
    const emoteSet = await getEmoteSet(client, stvResponse.emote_set.id)
    if (!hasTestEmote(emoteSet)) {
      throw new Error(`Emote ${TEST_EMOTE_NAME} not found in set`)
    }

    console.log('Removing test emote from active emote set...')
    await removeTestEmoteIfPresent(client, stvResponse.emote_set.id)
    addedTestEmote = false

    console.log('Emote set write test completed successfully')

    res.status(200).json({ message: 'Emote set test completed successfully' })
  } catch (error: unknown) {
    console.error('Error during emote set test:', error)
    Sentry.withScope((scope) => {
      scope.setTag('test-related', 'true')
      scope.setContext('testDetails', {
        emoteSetId: activeEmoteSetId,
        twitchId,
        userId,
      })
      Sentry.captureException(error)
    })
    const errorMessage = error instanceof Error ? error.message : String(error)
    res.status(500).json({ error: errorMessage, message: 'Internal server error' })
  } finally {
    if (addedTestEmote && activeEmoteSetId !== 'N/A') {
      try {
        await removeTestEmoteIfPresent(client, activeEmoteSetId)
      } catch (error) {
        console.error(`Failed to remove test emote from set ID ${activeEmoteSetId}:`, error)
        Sentry.captureException(error)
      }
    }
  }
}

function HeroCard({
  username,
  card,
  size = 'md',
  className = '',
}: {
  username: string
  card: HeroCardData
  size?: Size
  className?: string
}) {
  const planeRef = useRef<HTMLDivElement>(null)
  const reduced = useReducedMotion()
  const interactive = !reduced

  const meta = card.bestRarity ? RARITY_META[card.bestRarity] : undefined
  const accent = meta?.color ?? '#9146ff'
  const rank = meta?.rank ?? -1
  const t = tier(rank)
  const s = SIZE[size]

  const onMove = (e: PointerEvent<HTMLAnchorElement>) => {
    const el = planeRef.current
    if (!el || !interactive) {
      return
    }
    const r = e.currentTarget.getBoundingClientRect()
    const px = (e.clientX - r.left) / r.width
    const py = (e.clientY - r.top) / r.height
    el.style.setProperty('--rx', `${(0.5 - py) * 10}deg`)
    el.style.setProperty('--ry', `${(px - 0.5) * 10}deg`)
    el.style.setProperty('--mx', `${px * 100}%`)
    el.style.setProperty('--my', `${py * 100}%`)
    el.style.setProperty('--sheen', '1')
  }

  const reset = () => {
    const el = planeRef.current
    if (!el) {
      return
    }
    el.style.setProperty('--rx', '0deg')
    el.style.setProperty('--ry', '0deg')
    el.style.setProperty('--sheen', '0')
  }

  return (
    <Link
      href={`/${username}/set/${card.heroId}`}
      onPointerMove={onMove}
      onPointerLeave={reset}
      className={`group/card block rounded-2xl focus-visible:ring-2 focus-visible:ring-purple-400 focus-visible:outline-none ${className}`}
      style={{ perspective: interactive ? '900px' : undefined }}
      aria-label={`${card.heroName} — ${card.itemCount} cosmetics${meta ? `, up to ${meta.label}` : ''}`}
    >
      <div
        ref={planeRef}
        className='relative aspect-[5/7] overflow-hidden rounded-2xl border bg-gray-900 transition-transform duration-200 ease-out will-change-transform group-hover/card:-translate-y-0.5'
        style={{
          borderColor: t === 'flat' ? hexA(accent, 0.3) : hexA(accent, 0.55),
          boxShadow:
            t === 'chase'
              ? `0 0 0 1px ${hexA(accent, 0.8)}, 0 12px 40px ${hexA(accent, 0.28)}`
              : t === 'foil'
                ? `0 8px 30px ${hexA(accent, 0.16)}`
                : '0 6px 20px rgba(0,0,0,0.35)',
          transform: interactive ? 'rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg))' : undefined,
        }}
      >
        {/* Hero splash as the card face. */}
        {card.heroImg ? (
          <img
            src={card.heroImg}
            alt={card.heroName}
            loading='lazy'
            className='absolute inset-0 h-full w-full object-cover object-center'
          />
        ) : (
          <div
            aria-hidden
            className='absolute inset-0'
            style={{
              background: `radial-gradient(circle at 50% 35%, ${hexA(accent, 0.22)}, #0b0d12 70%)`,
            }}
          />
        )}

        {/* Rarity wash over the art so the card reads as its quality at a glance. */}
        <div
          aria-hidden
          className='absolute inset-0'
          style={{
            background: `linear-gradient(180deg, ${hexA(accent, t === 'flat' ? 0.04 : 0.1)} 0%, transparent 35%, rgba(8,10,14,0.55) 72%, rgba(8,10,14,0.96) 100%)`,
          }}
        />

        {/* Cursor-tracked sheen — the holographic sweep. Paint-only; off when reduced. */}
        {interactive && (
          <div
            aria-hidden
            className='pointer-events-none absolute inset-0 mix-blend-screen transition-opacity duration-200'
            style={{
              background: `radial-gradient(40% 30% at var(--mx,50%) var(--my,0%), ${hexA(accent, 0.5)}, transparent 70%)`,
              opacity: 'var(--sheen,0)' as unknown as number,
            }}
          />
        )}

        {/* Chase-only corner flourishes. */}
        {t === 'chase' && (
          <>
            <Corner pos='left-2 top-2' accent={accent} />
            <Corner pos='right-2 top-2 rotate-90' accent={accent} />
            <Corner pos='bottom-2 left-2 -rotate-90' accent={accent} />
            <Corner pos='bottom-2 right-2 rotate-180' accent={accent} />
          </>
        )}

        {card.justPlayed && (
          <span className='absolute top-2 left-2 rounded-full bg-black/55 px-2 py-0.5 text-[10px] font-semibold tracking-wider text-purple-200 uppercase ring-1 ring-purple-400/40 backdrop-blur-sm'>
            Just played
          </span>
        )}

        {/* Name / rarity / count strip. */}
        <div className='absolute inset-x-0 bottom-0 p-3'>
          <p className={`line-clamp-2 leading-tight font-bold text-white ${s.name}`}>
            {card.heroName}
          </p>
          <div
            className={`mt-1 flex items-center gap-1.5 font-semibold tracking-wider uppercase ${s.meta}`}
          >
            {meta && <span style={{ color: meta.color }}>{meta.label}</span>}
            {meta && <span className='text-gray-600'>·</span>}
            <span className='text-gray-400'>{card.itemCount} items</span>
          </div>
        </div>
      </div>
    </Link>
  )
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const session = await getServerSession(req, res, authOptions)
  if (!session?.user?.id) {
    res.status(401).json({ message: 'Unauthorized' })
    return
  }

  if (!session?.user?.role?.includes('admin')) {
    res.status(401).json({ error: 'Unauthorized' })
    return
  }

  try {
    const userId = session.user.id

    // Get gift type from query parameter or default to monthly
    const giftType = (req.query.giftType as string) || 'monthly'
    const validGiftTypes = ['monthly', 'annual', 'lifetime']

    if (!validGiftTypes.includes(giftType)) {
      res.status(400).json({ message: 'Invalid gift type. Must be monthly, annual, or lifetime' })
      return
    }

    // Get gift message from request body or use default
    const giftMessage =
      req.body?.giftMessage || 'This is a test gift message. Enjoy your subscription!'

    // Get gift quantity from request body or use default
    const giftQuantity = Number.parseInt(req.body?.giftQuantity || '1', 10)

    // Validate gift quantity
    if (Number.isNaN(giftQuantity) || giftQuantity < 1) {
      res.status(400).json({ message: 'Gift quantity must be a positive number' })
      return
    }

    // For lifetime, enforce quantity = 1
    const finalGiftQuantity = giftType === 'lifetime' ? 1 : giftQuantity

    // Check if user already has a lifetime subscription
    if (giftType === 'lifetime') {
      const existingLifetime = await prisma.subscription.findFirst({
        where: {
          OR: [
            {
              transactionType: 'LIFETIME',
            },
            {
              giftDetails: {
                giftType: 'lifetime',
              },
              isGift: true,
            },
          ],
          status: 'ACTIVE',
          userId,
        },
      })

      if (existingLifetime) {
        // For testing purposes, we'll still create the notification but add a warning
        console.warn(
          `User ${userId} already has a lifetime subscription but creating a test notification anyway`,
        )
      }
    }

    // Calculate the end date based on quantity
    const currentPeriodEnd = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) // 30 days from now

    // If quantity > 1, extend the period end date
    if (finalGiftQuantity > 1) {
      if (giftType === 'monthly') {
        // Add (quantity - 1) months to the end date
        currentPeriodEnd.setMonth(currentPeriodEnd.getMonth() + (finalGiftQuantity - 1))
      } else if (giftType === 'annual') {
        // Add (quantity - 1) years to the end date
        currentPeriodEnd.setFullYear(currentPeriodEnd.getFullYear() + (finalGiftQuantity - 1))
      }
    }

    // Create a test subscription with isGift flag
    const subscription = await prisma.subscription.create({
      data: {
        cancelAtPeriodEnd: false,
        currentPeriodEnd,
        isGift: true,
        status: 'ACTIVE',
        tier: 'PRO',
        transactionType: 'RECURRING',
        userId,
      },
    })

    // Create a gift subscription record
    const giftSubscription = await prisma.giftSubscription.create({
      data: {
        giftMessage,
        giftQuantity: finalGiftQuantity,
        giftType,
        senderName: 'Test Sender',
        subscriptionId: subscription.id,
      },
    })

    // Create a notification for the gift
    const notification = await prisma.notification.create({
      data: {
        giftSubscriptionId: giftSubscription.id,
        isRead: false,
        type: 'GIFT_SUBSCRIPTION',
        userId,
      },
    })

    // Get total active gift subscriptions for this user
    const activeGiftSubscriptions = await prisma.subscription.findMany({
      include: {
        giftDetails: true,
      },
      where: {
        isGift: true,
        status: 'ACTIVE',
        userId,
      },
    })

    // Calculate total gifted months
    let totalGiftedMonths = 0
    let hasLifetime = false

    for (const sub of activeGiftSubscriptions) {
      if (sub.giftDetails?.giftType === 'lifetime') {
        hasLifetime = true
        break
      }

      if (sub.giftDetails?.giftType === 'annual') {
        // Apply the gift quantity multiplier
        const quantity = sub.giftDetails.giftQuantity || 1
        totalGiftedMonths += 12 * quantity
      } else if (sub.giftDetails?.giftType === 'monthly') {
        // Apply the gift quantity multiplier
        const quantity = sub.giftDetails.giftQuantity || 1
        totalGiftedMonths += Number(quantity)
      }
    }

    res.status(200).json({
      giftSubscription,
      hasLifetime,
      message: 'Test gift notification created',
      notification,
      subscription,
      success: true,
      totalGiftedMonths: hasLifetime ? 'lifetime' : totalGiftedMonths,
    })
    return
  } catch (error) {
    console.error('Error creating test gift notification:', error)
    res.status(500).json({ error: String(error), message: 'Internal server error' })
    return
  }
}

