function buildCheckoutUrl(chargeId: string, hostedUrl?: string): string {
  const baseUrl =
    hostedUrl ||
    (process.env.VERCEL_ENV === 'production'
      ? `https://checkout.opennode.com/${chargeId}`
      : `https://checkout.dev.opennode.com/${chargeId}`)

  const params: string[] = []
  if (process.env.OPENNODE_CHECKOUT_DEFAULT_LN === 'true') {
    params.push('ln=1')
  }
  if (process.env.OPENNODE_CHECKOUT_HIDE_FIAT === 'true') {
    params.push('hf=1')
  }

  return params.length > 0 ? `${baseUrl}?${params.join('&')}` : baseUrl
}

