  const [wl, setWL] = useState<wlType>({
    records: [{ lose: 0, type: 'U', win: 0 }],
    statsDays: null,
  })
  const [radiantWinChance, setRadiantWinChance] = useState<WinChance | null>(null)

  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([])

  const [rankImageDetails, setRankImageDetails] = useState<{
    image: string | null
    rank: number | null
    leaderboard: number | null
    notLoaded?: boolean
  }>({
    image: '0.png',
    leaderboard: 0,
    notLoaded: true,
    rank: 0,
  })

  const [isInIframe, setIsInIframe] = useState(false)
  const isDevMode = useIsDevMode()
  const is404 = error && typeof error === 'object' && 'status' in error && error.status === 404

  // Add detection for OBS environment
  const [isOldObs, setIsOldObs] = useState(false)
  useEffect(() => {
    // Check if running in OBS (older Chromium)
    const isOldOBS =
      // New OBS uses browser source/docks CEF (Chromium) version 127 (6533)
      // Check if we're running in an older version that needs compatibility
      Number.parseInt(/Chrome\/(\d+)/.exec(navigator.userAgent)?.[1] || '999', 10) < 127

    setIsOldObs(isOldOBS)
  }, [])

  // Wait 10s after the first connect before showing MainScreenOverlays;
  // Reconnects after that show immediately.
  useEffect(() => {
    if (!connected) {
      return
    }
    if (hasShownOnce) {
      setShowMainScreenOverlay(true)
      return
    }
    const timer = setTimeout(() => {
      setShowMainScreenOverlay(true)
      setHasShownOnce(true)
    }, 10_000)
    return () => {
      clearTimeout(timer)
    }
  }, [connected, hasShownOnce])

  useEffect(() => {
    if (!original) {
      return
    }

    const steamAccount = original.SteamAccount?.[0]
    const rank = getRankDetail(
      steamAccount?.mmr ?? original.mmr ?? 0,
      steamAccount?.leaderboard_rank ?? null,
    )

    if (!rank) {
      return
    }

    const leaderboard =
      'standing' in rank ? rank.standing : (steamAccount?.leaderboard_rank ?? null)

    const rankDetails: {
      image: string
      rank: number
      leaderboard: number | null
      notLoaded: boolean
    } = {
      image: rank.myRank?.image ?? '0.png',
      leaderboard,
      notLoaded: false,
      rank: rank.mmr,
    }

    setRankImageDetails(rankDetails)
  }, [original])

  useStreamOfflineNotification(original?.stream_online, notification, refreshSettings)

  useEffect(() => {
    setIsInIframe(window.self !== window.top)
  }, [])

  useEffect(() => {
    if (error && !is404) {
      const status = (error as PotentialError)?.status
      // Skip transient network errors (no status -> SWR will retry) and 5xx
      // (already captured server-side in /api/settings). Report each status once.
      const isReportable = typeof status === 'number' && status < 500 && status !== 404
      if (isReportable && reportedErrorStatus.current !== status) {
        reportedErrorStatus.current = status
        Sentry.captureException(new Error('Error in overlay page fetching settings'), {
          extra: {
            message: (error as PotentialError)?.message,
            status,
          },
        })
      }
    } else {
      reportedErrorStatus.current = null
    }

    if (is404) {
      // For 404 errors, add local storage cache to prevent repeated API calls
      if (typeof window !== 'undefined' && window.localStorage) {
        try {
          // Store the invalid URL in local storage with timestamp
          const pathKey = `invalid_overlay_${window.location.pathname}`
          localStorage.setItem(
            pathKey,
            JSON.stringify({
              status: 404,
              timestamp: Date.now(),
            }),
          )
        } catch {
          // Ignore storage errors
        }
      }

      notification.open({
        description: 'Please delete your overlay and setup Dotabod again by visiting dotabod.com',
        duration: 0,
        key: 'auth-error',
        message: 'Authentication failed',
        placement: 'bottomLeft',
        type: 'error',
      })
    } else {
      notification.destroy('auth-error')
    }
  }, [error, notification, is404])

  useEffect(() => {
    if (!isDevMode) {
      return
    }
    setWL(devWL)
    setPollData(devPoll)
    setBlock(devBlockTypes)
    setRankImageDetails(devRank)
    setRadiantWinChance(devRadiantWinChance)
  }, [isDevMode])

  useSocket({
    setAegis,
    setBetData,
    setBlock,
    setChatMessages,
    setConnected,
    setNotablePlayers,
    setPaused,
    setPollData,
    setRadiantWinChance,
    setRankImageDetails,
    setRoshan,
    setWL,
  })

  useOBS({ block, connected })

  // This specific check might become redundant if _app.tsx handles it robustly.
  if (isInvalidLocalCheck) {
    return <InvalidOverlayPage />
  }

  if (is404) {
    // Return minimal content for 404s to reduce resource usage
    // This helps when users mistype URLs or accounts are deleted
    return (
      <>
        {/* oxlint-disable-next-line nextjs/no-duplicate-head -- conditional render path, only one Head per render */}
        <Head>
          <title>Dotabod | Invalid Overlay URL</title>
          <meta name='robots' content='noindex' />
        </Head>
        <style global jsx>{`
          html,
          body {
            overflow: hidden;
            background-color: transparent;
          }
        `}</style>
        <div className='hidden'>Invalid Dotabod overlay URL. Please check your OBS settings.</div>
      </>
    )
  }

  if (isDotabodDisabled) {
    return isDevMode ? (
      <>
        <motion.div
          className={clsx('absolute right-0 mt-9 block max-w-xs')}
          key='not-live'
          {...motionProps}
        >
          <Alert message='Dotabod is disabled!' />
        </motion.div>
        <Image
          key='dev-image'
          width={width}
          height={height}
          alt={`${block.type} dev screenshot`}
          src={`/images/dev/${width && height && Math.round((width / height) * 9) === 21 ? '21-9-' : ''}${block.type === 'spectator' ? 'playing' : (block.type ?? 'main-menu')}.png`}
        />
      </>
    ) : null
  }

  // Main overlay content for valid users
  return (
    <>
      <Head>
        <title>Dotabod | Stream overlays</title>
        {/* oxlint-disable-next-line nextjs/no-css-tags -- OBS legacy compatibility stylesheet */}
        {isOldObs && <link rel='stylesheet' href='/styles/obs-compat.css' />}
      </Head>
      <style global jsx>{`
        html,
        body {
          overflow: hidden;
        }
      `}</style>
      <DevControls
        block={block}
        setBlock={setBlock}
        showDevImage={showDevImage}
        setShowDevImage={setShowDevImage}
        chatMessages={chatMessages}
        setChatMessages={setChatMessages}
      />
      <AnimatePresence>
        <motion.div
          key='not-detected'
          {...motionProps}
          style={{ display: isInIframe && rankImageDetails?.notLoaded ? 'block' : 'none' }}
        >
          <div id='not-detected'>
            <Center style={{ height }}>
              <div className='space-y-6 rounded-md bg-gray-300 p-4'>
                <Spin spinning>
                  <div className='flex text-center'>
                    <div className='ml-3'>
                      <h3 className='text-2xl font-medium text-gray-800'>Waiting for Dota</h3>
                      <div className='mt-2 text-lg text-gray-700'>
                        <p>Dotabod hasn&apos;t detected your game yet.</p>
                      </div>
                    </div>
                  </div>
                </Spin>
              </div>
            </Center>
          </div>
        </motion.div>

        <OverlayV2>
          <RestrictFeature feature='livePolls'>
            <PollOverlays
              pollData={pollData}
              setBetData={setBetData}
              setPollData={setPollData}
              betData={betData}
              radiantWinChance={radiantWinChance}
            />
          </RestrictFeature>

          {showMainScreenOverlay && (
            <MainScreenOverlays
              key='main-screen-overlays'
              block={block}
              wl={wl}
              rankImageDetails={rankImageDetails}
            />
          )}

          <PickScreenOverlays
            block={block}
            key='hero-blocker-class'
            rankImageDetails={rankImageDetails}
            wl={wl}
          />

          <RestrictFeature feature='lastFmOverlay'>
            <AnimatedLastFm block={block} />
          </RestrictFeature>

          <InGameOutsideCenterV2>
            <RestrictFeature feature='autoTranslate'>
              <ChatMessagesOverlay chatMessages={chatMessages} />
            </RestrictFeature>
          </InGameOutsideCenterV2>
        </OverlayV2>

        <InGameOverlays
          key='in-game-overlays'
          block={block}
          wl={wl}
          rankImageDetails={rankImageDetails}
          paused={paused}
          roshan={roshan}
          setRoshan={setRoshan}
          setAegis={setAegis}
          aegis={aegis}
          notablePlayers={notablePlayers}
        />

        {isDevMode && showDevImage && (
          <Image
            key='dev-image'
            width={width}
            height={height}
            alt={`${block.type} dev screenshot`}
            src={`/images/dev/${width && height && Math.round((width / height) * 9) === 21 ? '21-9-' : ''}${block.type === 'spectator' ? 'playing' : (block.type ?? 'main-menu')}.png`}
          />
        )}
      </AnimatePresence>
      <DevModeToggle />
    </>
  )
}

