    onChange?: (value: number | null) => void
    precision?: number
    value?: number | null
  }) => (
    <input
      {...props}
      type='number'
      value={value ?? ''}
      onChange={(event) => {
        onChange?.(event.currentTarget.value === '' ? null : Number(event.currentTarget.value))
      }}
    />
  )

  type RadioButtonProps = {
    checked?: boolean
    children: ReactNode
    disabled?: boolean
    onChange?: (event: { target: { value: number } }) => void
    value?: number
  }

  const RadioButton = ({ children, checked, disabled, onChange, value }: RadioButtonProps) => (
    <label>
      <input
        checked={checked}
        disabled={disabled}
        type='radio'
        value={value}
        onChange={() => {
          onChange?.({ target: { value: value ?? 0 } })
        }}
      />
      {children}
    </label>
  )

  const RadioGroup = ({
    'aria-label': ariaLabel,
    children,
    disabled,
    onChange,
    value,
  }: {
    'aria-label'?: string
    children: ReactNode
    disabled?: boolean
    onChange?: (event: { target: { value: number } }) => void
    value?: number
  }) => (
    <div aria-label={ariaLabel} role='radiogroup'>
      {Children.map(children, (child) => {
        if (!isValidElement<RadioButtonProps>(child)) {
          return child
        }

        return cloneElement(child, {
          checked: child.props.value === value,
          disabled: disabled || child.props.disabled,
          onChange,
        })
      })}
    </div>
  )

  const SkeletonInput = ({ style }: { style?: CSSProperties }) => (
    <div aria-busy='true' style={style} />
  )

  return {
    Button,
    Form,
    Input,
    InputNumber,
    Radio: { Button: RadioButton, Group: RadioGroup },
    Skeleton: { Input: SkeletonInput },
  }
})

function describeMutationFailure(status?: number): string {
  if (status === 403) {
    return "You don't have permission to change this setting."
  }
  if (status === 401) {
    return "Couldn't save. Sign in again."
  }
  if (status === 400 || status === 422) {
    return "That setting can't be set to this value."
  }
  if (status === 429) {
    return "You're changing settings too quickly. Try again in a moment."
  }
  if (status === undefined) {
    return "Couldn't reach the server. Check your connection."
  }
  return "Couldn't save. Try again in a moment."
}

