function rankTierToMmr(rankTier: string | number) {
  if (!Number(rankTier)) {
    return 0
  }
  const intRankTier = Number(rankTier)

  // Just gonna guess an immortal without standing is 6k mmr
  if (intRankTier > 77) {
    // Get the highest MMR from the ranks array
    const highestRankMMR = ranks.at(-1)?.range[1] || 5619
    return highestRankMMR + 50
  }

  // Floor to 5
  const stars = intRankTier % 10 > 5 ? 5 : intRankTier % 10
  const rank = ranks.find((rank) =>
    rank.image.startsWith(`${Math.floor(Number(intRankTier / 10))}${stars}`),
  )

  // Middle of range
  return ((rank?.range[0] ?? 0) + (rank?.range[1] ?? 0)) / 2
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    res.status(405).json({ message: 'Method Not Allowed' })
    return
  }

  const session = await getServerSession(req, res, authOptions)

  if (!session?.user?.id) {
    res.status(403).json({ message: 'Forbidden' })
    return
  }

  try {
    res.setHeader('Cache-Control', 'private, max-age=15, stale-while-revalidate=30')

    const { providerAccountId, accessToken, error } = await getTwitchTokens(session.user.id)
    if (error) {
      res.status(403).json({ message: 'Forbidden' })
      return
    }

    const banResponse = await checkBan(providerAccountId, accessToken)

    // Also check for disable reasons related to bot bans
    const commandDisableSetting = await prisma.setting.findFirst({
      select: {
        autoDisabledAt: true,
        disableMetadata: true,
        disableReason: true,
        value: true,
      },
      where: {
        key: 'commandDisable',
        userId: session.user.id,
      },
    })

    const response = {
      ...banResponse,
      disableMetadata: commandDisableSetting?.disableMetadata,
      disableReason: commandDisableSetting?.disableReason,
      disabled: commandDisableSetting?.value === true,
      disabledAt: commandDisableSetting?.autoDisabledAt,
    }

    res.status(200).json(response)
    return
  } catch (error) {
    captureException(error)
    res.status(500).json({ error: error.message, message: 'Failed to get ban info' })
    return
  }
}

