function aggregateGiftDuration(
  giftType: string,
  quantity: number,
  existingExpiration: Date | null = null,
  startDate: Date = new Date(),
): Date {
  // For lifetime gifts, always return a far future date
  if (giftType === 'lifetime') {
    const lifetimeDate = new Date(startDate)
    lifetimeDate.setFullYear(lifetimeDate.getFullYear() + 100)
    return lifetimeDate
  }

  // Check if existing expiration is already a lifetime subscription
  if (existingExpiration && existingExpiration.getFullYear() >= 2100) {
    return existingExpiration // Keep the existing lifetime subscription
  }

  // Determine the base date to start from
  const baseDate =
    existingExpiration && existingExpiration > startDate ? new Date(existingExpiration) : startDate

  // Calculate the new end date
  return calculateGiftEndDate(giftType, quantity, baseDate)
}

function Hero({ data, team }: MinimapUnitProps) {
  const heroUnits = useSelector(selectHeroUnits)
  // Default, custom, or icon
  const rawDisplayType = useSelector(selectSettings)?.hero_display
  const displayType: string = typeof rawDisplayType === 'string' ? rawDisplayType : 'icon'
  const mainHero = useSelector(selectMainHero)

  const position = {
    bottom: data.yposP,
    left: data.xposP,
  }

  const isEnemy = data.teamP !== team
  const isIllusion = data.image === 'heroimage' || data.image === 'enemyimage'
  const isBrewmaster = data.name === 'brewmaster'

  const brewlingCount = heroUnits.filter((unit) => unit.unitname.includes('brewmaster')).length
  const hasBrewlings = brewlingCount >= 3

  const rotation = {
    transform: `rotate(${data.yaw * -1}deg)`,
  }

  const pointerIcon = isEnemy
    ? '/images/overlay/minimap/blocker/icons/arrows/enemy-pointer.png'
    : '/images/overlay/minimap/blocker/icons/arrows/hero-pointer.png'

  let heroIcon: string
  if (displayType === 'default') {
    if (isEnemy) {
      heroIcon = '/images/overlay/minimap/blocker/icons/arrows/enemy.png'
    } else if (data.name === mainHero) {
      heroIcon = '/images/overlay/minimap/blocker/icons/arrows/hero-main.png'
    } else {
      heroIcon = '/images/overlay/minimap/blocker/icons/arrows/hero.png'
    }
  } else {
    heroIcon = `https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/icons/${data.name}.png`
  }

  return (
    <div className={`container-hero ${displayType}`} style={position}>
      {!(isBrewmaster && hasBrewlings) && (
        <>
          {displayType === 'custom' && (
            <img
              title={data.name}
              alt='hero icon'
              className={['pointer', isEnemy ? 'enemy' : '', isIllusion ? 'illusion' : ''].join(
                ' ',
              )}
              style={rotation}
              src={pointerIcon}
            />
          )}
          <img
            title={data.name}
            alt='hero icon'
            className={['icon', isEnemy ? 'enemy' : '', isIllusion ? 'illusion' : ''].join(' ')}
            style={displayType === 'default' ? rotation : {}}
            src={heroIcon}
          />
        </>
      )}
    </div>
  )
}

