useEffect(() => {
    if (isOverlay || status === 'loading') {
      return
    }

    window._hsq = window._hsq || []
    window.hsConversationsOnReady = window.hsConversationsOnReady || []
    // Keep the widget from auto-loading before identity resolves, but preserve any
    // Identification already set on a previous run so we don't transiently drop it.
    window.hsConversationsSettings = {
      ...window.hsConversationsSettings,
      loadImmediately: false,
    }

    // Each effect run owns its own `cancelled` flag; the cleanup flips it so any
    // Queued onReady callback from a superseded run becomes a no-op.
    let cancelled = false

    const loadWith = (identity?: { email: string; token: string }) => {
      if (cancelled) {
        return
      }

      window.hsConversationsSettings = identity
        ? {
            identificationEmail: identity.email,
            identificationToken: identity.token,
            loadImmediately: false,
          }
        : { loadImmediately: false }

      const run = () => {
        if (cancelled) {
          return
        }
        // Re-identifying (login/logout without a full reload) requires resetting
        // The widget before it reloads with the new identity.
        if (loadedRef.current) {
          window.HubSpotConversations?.clear?.({ resetWidget: true })
        }
        window.HubSpotConversations?.widget?.load()
        loadedRef.current = true
      }

      if (window.HubSpotConversations) {
        run()
      } else {
        window.hsConversationsOnReady?.push(run)
      }
    }

    if (status === 'authenticated' && data?.user?.email) {
      fetch('/api/hubspot/visitor-token')
        .then((res) => (res.ok && res.status !== 204 ? res.json() : null))
        .then((payload: { email?: string; token?: string } | null) => {
          if (cancelled) {
            return
          }
          if (payload?.email && payload?.token) {
            window._hsq.push(['identify', { email: payload.email, name: data.user?.name }])
            // Identify is only transmitted to HubSpot on the next trackPageView.
            window._hsq.push(['trackPageView'])
            loadWith({ email: payload.email, token: payload.token })
          } else if (!loadedRef.current) {
            // No identity available and nothing loaded yet — still show the widget.
            loadWith()
          }
        })
        .catch(() => {
          // Don't downgrade an already-identified widget; only load if nothing has.
          if (!cancelled && !loadedRef.current) {
            loadWith()
          }
        })
    } else {
      // Anonymous visitor: load the widget without identification.
      loadWith()
    }

    return () => {
      cancelled = true
    }
  }, [isOverlay, status, data?.user?.email])

async function buildCollectionSummary(
  loadouts: { heroId: number; heroName: string; items: unknown }[],
): Promise<CollectionSummary> {
  // The count only needs the row count, so it stays reliable even if a row's items
  // JSON is malformed. The decorative cards/tally are best-effort below.
  const count = loadouts.length
  if (!count) {
    return { count: 0, cards: [], tally: [] }
  }

  // A row's items can be null or a non-array shape from an older/partial capture;
  // coerce so a bad row can never throw and 404 the whole profile page.
  const itemsOf = (items: unknown): CosmeticItem[] =>
    Array.isArray(items) ? (items as CosmeticItem[]) : []

  try {
    const heroes = (await import('dotaconstants/build/heroes.json')).default as Record<
      string,
      { img?: string }
    >

    const cards = loadouts
      .map((l) => {
        const img = heroes[String(l.heroId)]?.img
        return {
          bestRarity: bestRarity(itemsOf(l.items)) ?? null,
          heroId: l.heroId,
          heroImg: img ? `${STEAM_CDN}${img}` : null,
          heroName: l.heroName,
        }
      })
      .sort(
        (a, b) =>
          (b.bestRarity ? (RARITY_META[b.bestRarity]?.rank ?? -1) : -1) -
          (a.bestRarity ? (RARITY_META[a.bestRarity]?.rank ?? -1) : -1),
      )
      .slice(0, 5)

    const tallyCounts = new Map<string, number>()
    for (const l of loadouts) {
      for (const item of itemsOf(l.items))
        if (rarityRank(item) >= 4)
          tallyCounts.set(item.rarity as string, (tallyCounts.get(item.rarity as string) ?? 0) + 1)
    }
    const tally = [...tallyCounts.entries()]
      .map(([rarity, count]) => ({ count, rarity }))
      .sort((a, b) => (RARITY_META[b.rarity]?.rank ?? 0) - (RARITY_META[a.rarity]?.rank ?? 0))
      .slice(0, 3)

    return { cards, count, tally }
  } catch (error) {
    // Never let cosmetic shaping break the page — fall back to the bare count.
    console.error('Error building collection summary:', error)
    return { cards: [], count, tally: [] }
  }
}

