async function handler(req: NextApiRequest, res: NextApiResponse) {
  const session = await getServerSession(req, res, authOptions)

  if (!session?.user?.id) {
    res.status(403).json({ message: 'Forbidden' })
    return
  }

  if (req.method === 'POST') {
    try {
      const { settingKey, autoResolved = false } = req.body

      if (!settingKey) {
        res.status(400).json({ message: 'Setting key is required' })
        return
      }

      const now = new Date()

      await prisma.$transaction(async (tx) => {
        // Clear disable reason from setting
        await tx.setting.updateMany({
          data: {
            autoDisabledAt: null,
            autoDisabledBy: null,
            disableMetadata: undefined,
            disableReason: null,
            updatedAt: now,
          },
          where: {
            key: settingKey,
            userId: session.user.id,
          },
        })

        // Mark notifications as resolved
        await tx.disableNotification.updateMany({
          data: {
            autoResolved,
            resolvedAt: now,
          },
          where: {
            resolvedAt: null,
            settingKey,
            userId: session.user.id,
          },
        })
      })

      res.status(200).json({ message: 'Disable reason resolved successfully' })
      return
    } catch (error) {
      captureException(error)
      res.status(500).json({
        error: error instanceof Error ? error.message : 'Unknown error',
        message: 'Failed to resolve disable reason',
      })
      return
    }
  }

  res.status(405).json({ message: 'Method Not Allowed' })
}

