function bestRarity(items: CosmeticItem[]): string | undefined {
  let best: string | undefined
  let bestRank = -1
  for (const i of items) {
    const rank = rarityRank(i)
    if (rank > bestRank) {
      bestRank = rank
      best = i.rarity
    }
  }
  return best
}

