async function hsFetch(url: string, init: RequestInit, retries = 5): Promise<Response> {
  for (let attempt = 0; ; attempt++) {
    const now = Date.now()
    const wait = Math.max(0, nextSlot - now)
    nextSlot = Math.max(now, nextSlot) + MIN_INTERVAL_MS
    if (wait > 0) {
      await new Promise((r) => setTimeout(r, wait))
    }

    const res = await fetch(url, init)
    if (res.status !== 429 || attempt >= retries) {
      return res
    }
    const retryAfter = Number(res.headers.get('Retry-After'))
    const backoff =
      Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : 1000 * (attempt + 1)
    await res.body?.cancel()
    await new Promise((r) => setTimeout(r, backoff))
  }
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  // Extract steam32Id from request body
  const { steam32Id } = req.body

  if (!steam32Id) {
    res.status(400).json({ message: 'Missing steam32Id parameter' })
    return
  }

  try {
    // Get the user session
    const session = await getServerSession(req, res, authOptions)

    if (!session?.user?.id) {
      res.status(401).json({ message: 'Unauthorized' })
      return
    }

    // Check if the steam32Id is associated with the user
    const steamAccount = await prisma.steamAccount.findFirst({
      where: {
        OR: [{ userId: session.user.id }, { connectedUserIds: { has: session.user.id } }],
        steam32Id: Number.parseInt(steam32Id.toString(), 10),
      },
    })

    if (!steamAccount) {
      res.status(404).json({ message: 'Steam account not found or not associated with the user' })
      return
    }

    // Fetch profile data from OpenDota API
    const accountId = Number.parseInt(steam32Id.toString(), 10)
    const profile = await fetchOpenDotaProfile(accountId)

    if (!profile) {
      res.status(404).json({ message: 'Failed to fetch profile data from OpenDota' })
      return
    }

    // Estimate MMR from rank tier if available
    const estimatedMMR = profile.rank_tier ? rankTierToMmr(profile.rank_tier) : 0

    // Update the steam account with the new MMR and leaderboard rank
    const updatedAccount = await prisma.steamAccount.update({
      data: {
        leaderboard_rank: profile.leaderboard_rank || null,
        mmr: estimatedMMR,
        updatedAt: new Date(),
      },
      where: {
        steam32Id: accountId,
      },
    })

    res.status(200).json({
      data: {
        leaderboardRank: updatedAccount.leaderboard_rank,
        mmr: updatedAccount.mmr,
        steam32Id: updatedAccount.steam32Id,
      },
      profile,
      success: true,
    })
    return
  } catch (error) {
    captureException(error)
    console.error('Error updating Steam account profile data:', error)
    res.status(500).json({ message: 'Internal server error' })
    return
  }
}

async function getMatchData(matchId: string, heroId: number) {
  // Check if we already have this match data cached
  if (matchDataCache.has(matchId)) {
    console.log(`[MMR] Using cached match data for matchId: ${matchId}`)
    return matchDataCache.get(matchId)
  }

  try {
    const opendotaMatch = await axios(`https://api.opendota.com/api/matches/${matchId}`)

    // If the match data is incomplete, we might need to request parsing
    if (!opendotaMatch.data?.players) {
      console.log(`[MMR] Match ${matchId} data incomplete, attempting to request parsing`)
      try {
        const jobId = await createJob(matchId)
        await getJobStatus(jobId)
        // After job completes, try fetching the match data again
        return getMatchData(matchId, heroId)
      } catch (error) {
        console.error(`[MMR] Failed to parse match ${matchId}:`, error)
        throw new Error(`Match ${matchId} not available or not ready to be parsed`, {
          cause: error,
        })
      }
    }

    let radiantWin = null
    let lobbyType = null
    const moreData = {
      assists: 0,
      deaths: 0,
      direScore: 0,
      kills: 0,
      radiantScore: 0,
    }

    if (Array.isArray(opendotaMatch.data?.players)) {
      if (typeof opendotaMatch?.data?.radiant_win === 'boolean') {
        radiantWin = opendotaMatch?.data?.radiant_win
        moreData.radiantScore = opendotaMatch?.data?.radiant_score || 0
        moreData.direScore = opendotaMatch?.data?.dire_score || 0
      }

      // Extract player-specific stats if heroId is provided
      if (heroId) {
        const player = opendotaMatch.data.players.find(
          (p: { hero_id: number }) => p.hero_id === heroId,
        )
        if (player) {
          moreData.kills = player.kills || 0
          moreData.deaths = player.deaths || 0
          moreData.assists = player.assists || 0
        }
      }

      if (typeof opendotaMatch?.data?.lobby_type === 'number') {
        lobbyType = opendotaMatch?.data?.lobby_type
      }
    } else {
      throw new TypeError('Match data is incomplete')
    }

    const result = {
      lobbyType,
      matchId,
      radiantWin,
      ...moreData,
    }

    // Cache the result
    matchDataCache.set(matchId, result)

    return result
  } catch (error) {
    console.error(`[MMR] Error fetching match ${matchId}:`, error)
    throw new Error(`Failed to fetch match data for ${matchId}`, { cause: error })
  }
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const session = await getServerSession(req, res, authOptions)

  const userId = req.query.id as string | undefined
  const username = req.query.username as string | undefined

  if (username) {
    if (req.method === 'GET') {
      try {
        res.setHeader('Cache-Control', 'public, s-maxage=30, stale-while-revalidate=120')

        // Use findFirst instead of findFirstOrThrow to handle not found cases gracefully
        const data = await prisma.user.findFirst({
          select: {
            Account: {
              select: {
                providerAccountId: true,
              },
            },
            createdAt: true,
            displayName: true,
            image: true,
            name: true,
            settings: {
              select: {
                key: true,
                value: true,
              },
              where: {
                key: {
                  startsWith: 'command',
                },
              },
            },
            stream_online: true,
            subscription: {
              ...subscriptionRelationQuery,
            },
          },
          where: {
            name: username.toLowerCase(),
          },
        })

        if (!data) {
          res.json({})
          return
        }

        const subscription = getSettingsSubscription(data.subscription)

        const { Account, subscription: _subscriptionRows, ...userData } = data

        res.json({
          ...userData,
          subscription,
          twitchId: Account?.providerAccountId ?? null,
        })
        return
      } catch (error) {
        captureException(error)
        console.error(error)
        res.status(404).json({
          error: 'User not found',
        })
        return
      }
    }
  }

  if (!userId && !session?.user?.id) {
    res.status(403).json({ message: 'Unauthorized' })
    return
  }

  if (req.method === 'GET') {
    try {
      const resolvedUserId = userId ?? session?.user?.id
      if (!resolvedUserId) {
        res.status(403).json({ message: 'Unauthorized' })
        return
      }

      const isPublicOverlayRequest = Boolean(userId)
      res.setHeader('Cache-Control', 'private, no-store')

      const data = await prisma.user.findFirst({
        select: {
          Account: {
            select: {
              providerAccountId: true,
            },
          },
          SteamAccount: {
            select: {
              leaderboard_rank: true,
              mmr: true,
              steam32Id: true,
            },
          },
          beta_tester: true,
          locale: true,
          mmr: true,
          settings: {
            select: {
              key: true,
              value: true,
            },
          },
          steam32Id: true,
          stream_online: true,
          subscription: {
            ...subscriptionRelationQuery,
          },
        },
        where: {
          id: resolvedUserId,
        },
      })

      if (!data) {
        res.status(404).json({ message: 'User not found' })
        return
      }

      if (isPublicOverlayRequest || session?.user?.isImpersonating) {
        // Filter out obsServerPassword
        data.settings = data.settings.filter(
          (setting) => setting.key !== Settings.obsServerPassword,
        )
      }

      const subscription = getSettingsSubscription(data.subscription)

      const { subscription: _subscriptionRows, ...userData } = data

      res.json({
        ...userData,
        subscription,
      })
      return
    } catch (error) {
      captureException(error)
      console.error('Error fetching user:', error)
      return res.status(500).end()
    }
  }

  if (req.method === 'POST') {
    if (!session?.user?.id) {
      res.status(403).json({ message: 'Unauthorized' })
      return
    }

    try {
      const parsedBody = JSON.parse(req.body)

      const keyValidation = settingKeySchema.safeParse(parsedBody.key)
      if (!keyValidation.success) {
        res.status(422).json({ error: 'Invalid setting key' })
        return
      }

      // Get user's subscription
      const subscription = await getSubscription(session.user.id)
      const validKey = keyValidation.data
      const schema = dynamicSettingSchema(validKey, subscription)

      try {
        const validatedBody = schema.parse(parsedBody)

        if (session.user.isImpersonating) {
          if (validatedBody.key === Settings.obsServerPassword) {
            res.status(403).json({ message: 'Forbidden' })
            return
          }
        }

        const settingValue: Prisma.InputJsonValue | typeof Prisma.JsonNull =
          [Settings.wlStatsDays, Settings.wlStatsStartDate].includes(validatedBody.key as never) &&
          validatedBody.value === null
            ? Prisma.JsonNull
            : (validatedBody.value as Prisma.InputJsonValue)

        const post = await prisma.setting.create({
          data: {
            key: validatedBody.key,
            userId: session.user.id,
            value: settingValue,
          },
          select: {
            id: true,
          },
        })

        res.json(post)
        return
      } catch (error) {
        if (error instanceof z.ZodError) {
          // Check if error is related to subscription access
          const subscriptionError = error.errors.find(
            (e) => e.message === 'Your subscription tier does not have access to this feature',
          )
          if (subscriptionError) {
            res.status(403).json({
              error: 'Subscription tier does not have access to this feature',
              requiredTier: FEATURE_TIERS[validKey],
            })
            return
          }
          res.status(422).json(error.issues)
          return
        }
        throw error
      }
    } catch (error) {
      captureException(error)
      console.error('Error creating setting:', error)
      return res.status(500).end()
    }
  }
}

