async function queryLnaPermission(): Promise<LnaPermissionState> {
  // LNA requires secure context
  if (!isSecureContext()) {
    return 'unsupported'
  }

  // Check if Permissions API is available
  if (typeof navigator === 'undefined' || !('permissions' in navigator)) {
    return 'unsupported'
  }

  try {
    // Type assertion needed because TypeScript doesn't know about 'local-network-access' yet
    const result = await navigator.permissions.query({
      name: 'local-network-access' as PermissionName,
    })
    return result.state
  } catch {
    // Permission name not recognized or other error
    return 'unsupported'
  }
}

