async function verifyOpenNodeWebhook(eventData: unknown): Promise<boolean> {
  try {
    if (
      typeof eventData !== 'object' ||
      eventData === null ||
      !('hashed_order' in eventData) ||
      typeof eventData.hashed_order !== 'string'
    ) {
      return false
    }
    const webhookData = eventData as Parameters<typeof signatureIsValid>[0]
    const isValid = signatureIsValid(webhookData)

    // Add debugging info in development
    if (process.env.VERCEL_ENV !== 'production') {
      console.log('OpenNode signature verification:', {
        chargeId: webhookData.id,
        description: webhookData.description,
        hashedOrder: webhookData.hashed_order,
        isValid,
      })
    }

    return isValid
  } catch (error) {
    console.error('OpenNode signature verification failed:', error)
    return false
  }
}

