            for (const subscription of activeSubscriptions) {
              // If it's a regular Stripe subscription (not crypto), cancel it in Stripe
              if (
                subscription.stripeSubscriptionId &&
                !subscription.stripeSubscriptionId.startsWith('crypto_')
              ) {
                try {
                  console.log(`Canceling Stripe subscription ${subscription.stripeSubscriptionId}`)
                  await stripe.subscriptions.cancel(subscription.stripeSubscriptionId, {
                    invoice_now: false,
                    prorate: true,
                  })
                } catch (error) {
                  console.error(
                    `Failed to cancel Stripe subscription ${subscription.stripeSubscriptionId}:`,
                    error,
                  )
                }
              }

              const baseMetadata =
                typeof subscription.metadata === 'object' &&
                subscription.metadata !== null &&
                !Array.isArray(subscription.metadata)
                  ? { ...(subscription.metadata as Record<string, unknown>) }
                  : {}

              const renewalInvoiceId =
                typeof baseMetadata.renewalInvoiceId === 'string'
                  ? baseMetadata.renewalInvoiceId
                  : null

              if (renewalInvoiceId) {
                await cancelInvoiceIfPending(
                  renewalInvoiceId,
                  `subscription ${subscription.id} during lifetime upgrade`,
                )
                delete baseMetadata.renewalInvoiceId
                delete baseMetadata.renewalDueDate
              }

              // Update subscription status in our database
              await tx.subscription.update({
                data: {
                  cancelAtPeriodEnd: true,
                  metadata: {
                    ...baseMetadata,
                    upgradedAt: new Date().toISOString(),
                    upgradedToLifetime: 'true',
                  },
                  status: SubscriptionStatus.CANCELED,
                  updatedAt: new Date(),
                },
                where: { id: subscription.id },
              })

              console.log(
                `Marked subscription ${subscription.id} as canceled due to lifetime upgrade`,
              )
            }

            // Create the lifetime purchase
            console.log(
              `Creating lifetime purchase for user ${userId} because price ID ${priceId} is a lifetime price`,
            )
            await createLifetimePurchase(userId, session.customer as string, priceId, tx, {
              checkoutSessionId: session.id,
            })
            return true
          }

          console.error(
            `Skipping subscription creation - no price ID found for session ${session.id}`,
          )
          return true
        }

        return false
      },
      `handleCheckoutCompleted(${session.id})`,
      session.metadata?.userId,
    )) !== null
  )
}

async function handler(_req: NextApiRequest, res: NextApiResponse) {
  try {
    const latest = getLatestPost()
    const post = latest
      ? {
          date: latest.date,
          description: latest.description,
          slug: latest.slug,
          title: latest.title,
        }
      : null

    res.setHeader('Cache-Control', 's-maxage=3600, stale-while-revalidate')
    res.status(200).json({ post })
    return
  } catch (error) {
    captureException(error)
    return res.status(500).end()
  }
}

function HeroCard({
  username,
  card,
  size = 'md',
  className = '',
}: {
  username: string
  card: HeroCardData
  size?: Size
  className?: string
}) {
  const planeRef = useRef<HTMLDivElement>(null)
  const reduced = useReducedMotion()
  const interactive = !reduced

  const meta = card.bestRarity ? RARITY_META[card.bestRarity] : undefined
  const accent = meta?.color ?? '#9146ff'
  const rank = meta?.rank ?? -1
  const t = tier(rank)
  const s = SIZE[size]

  const onMove = (e: PointerEvent<HTMLAnchorElement>) => {
    const el = planeRef.current
    if (!el || !interactive) {
      return
    }
    const r = e.currentTarget.getBoundingClientRect()
    const px = (e.clientX - r.left) / r.width
    const py = (e.clientY - r.top) / r.height
    el.style.setProperty('--rx', `${(0.5 - py) * 10}deg`)
    el.style.setProperty('--ry', `${(px - 0.5) * 10}deg`)
    el.style.setProperty('--mx', `${px * 100}%`)
    el.style.setProperty('--my', `${py * 100}%`)
    el.style.setProperty('--sheen', '1')
  }

  const reset = () => {
    const el = planeRef.current
    if (!el) {
      return
    }
    el.style.setProperty('--rx', '0deg')
    el.style.setProperty('--ry', '0deg')
    el.style.setProperty('--sheen', '0')
  }

  return (
    <Link
      href={`/${username}/set/${card.heroId}`}
      onPointerMove={onMove}
      onPointerLeave={reset}
      className={`group/card block rounded-2xl focus-visible:ring-2 focus-visible:ring-purple-400 focus-visible:outline-none ${className}`}
      style={{ perspective: interactive ? '900px' : undefined }}
      aria-label={`${card.heroName} — ${card.itemCount} cosmetics${meta ? `, up to ${meta.label}` : ''}`}
    >
      <div
        ref={planeRef}
        className='relative aspect-[5/7] overflow-hidden rounded-2xl border bg-gray-900 transition-transform duration-200 ease-out will-change-transform group-hover/card:-translate-y-0.5'
        style={{
          borderColor: t === 'flat' ? hexA(accent, 0.3) : hexA(accent, 0.55),
          boxShadow:
            t === 'chase'
              ? `0 0 0 1px ${hexA(accent, 0.8)}, 0 12px 40px ${hexA(accent, 0.28)}`
              : t === 'foil'
                ? `0 8px 30px ${hexA(accent, 0.16)}`
                : '0 6px 20px rgba(0,0,0,0.35)',
          transform: interactive ? 'rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg))' : undefined,
        }}
      >
        {/* Hero splash as the card face. */}
        {card.heroImg ? (
          <img
            src={card.heroImg}
            alt={card.heroName}
            loading='lazy'
            className='absolute inset-0 h-full w-full object-cover object-center'
          />
        ) : (
          <div
            aria-hidden
            className='absolute inset-0'
            style={{
              background: `radial-gradient(circle at 50% 35%, ${hexA(accent, 0.22)}, #0b0d12 70%)`,
            }}
          />
        )}

        {/* Rarity wash over the art so the card reads as its quality at a glance. */}
        <div
          aria-hidden
          className='absolute inset-0'
          style={{
            background: `linear-gradient(180deg, ${hexA(accent, t === 'flat' ? 0.04 : 0.1)} 0%, transparent 35%, rgba(8,10,14,0.55) 72%, rgba(8,10,14,0.96) 100%)`,
          }}
        />

        {/* Cursor-tracked sheen — the holographic sweep. Paint-only; off when reduced. */}
        {interactive && (
          <div
            aria-hidden
            className='pointer-events-none absolute inset-0 mix-blend-screen transition-opacity duration-200'
            style={{
              background: `radial-gradient(40% 30% at var(--mx,50%) var(--my,0%), ${hexA(accent, 0.5)}, transparent 70%)`,
              opacity: 'var(--sheen,0)' as unknown as number,
            }}
          />
        )}

        {/* Chase-only corner flourishes. */}
        {t === 'chase' && (
          <>
            <Corner pos='left-2 top-2' accent={accent} />
            <Corner pos='right-2 top-2 rotate-90' accent={accent} />
            <Corner pos='bottom-2 left-2 -rotate-90' accent={accent} />
            <Corner pos='bottom-2 right-2 rotate-180' accent={accent} />
          </>
        )}

        {card.justPlayed && (
          <span className='absolute top-2 left-2 rounded-full bg-black/55 px-2 py-0.5 text-[10px] font-semibold tracking-wider text-purple-200 uppercase ring-1 ring-purple-400/40 backdrop-blur-sm'>
            Just played
          </span>
        )}

        {/* Name / rarity / count strip. */}
        <div className='absolute inset-x-0 bottom-0 p-3'>
          <p className={`line-clamp-2 leading-tight font-bold text-white ${s.name}`}>
            {card.heroName}
          </p>
          <div
            className={`mt-1 flex items-center gap-1.5 font-semibold tracking-wider uppercase ${s.meta}`}
          >
            {meta && <span style={{ color: meta.color }}>{meta.label}</span>}
            {meta && <span className='text-gray-600'>·</span>}
            <span className='text-gray-400'>{card.itemCount} items</span>
          </div>
        </div>
      </div>
    </Link>
  )
}

