            <li aria-hidden className='text-gray-700'>
              ·
            </li>
            <li>Cancel anytime</li>
          </ul>
        </div>
      )}

      <Wrapper>
        <div className='mt-8 flex justify-center'>
          <PeriodToggle activePeriod={activePeriod} onChange={setActivePeriod} />
