function isPaypalSubscription(
  subscription: { metadata?: unknown; stripeSubscriptionId?: string | null } | null | undefined,
): boolean {
  if (!subscription) {
    return false
  }
  if (subscription.stripeSubscriptionId) {
    return subscription.stripeSubscriptionId.startsWith('paypal_')
  }
  const metadata =
    subscription.metadata &&
    typeof subscription.metadata === 'object' &&
    !Array.isArray(subscription.metadata)
      ? (subscription.metadata as Record<string, unknown>)
      : null
  return metadata?.paymentProvider === 'paypal'
}

function isInGracePeriod(): boolean {
  return new Date() < GRACE_PERIOD_END
}

function tierForRank(mmr: number, standing: number | null): StreamerTier {
  const divineMax = ranks.at(-1)?.range[1] ?? 5629
  if ((standing && standing > 0) || mmr > divineMax) {
    return 'immortal'
  }
  if (!mmr || mmr <= 0) {
    return 'unranked'
  }
  const tier = rankTiers.find((t) => {
    if (t.key === 'immortal') {
      return false
    }
    const range = tierMmrRange(t.key)
    return (
      range != null && mmr >= (range.gte ?? 0) && mmr <= (range.lte ?? Number.POSITIVE_INFINITY)
    )
  })
  return (tier?.key as StreamerTier) ?? 'unranked'
}

