    }
    if (paypalSubs.length) {
      console.warn('   PayPal subscriptions:', paypalSubs)
    }
  }

  await prisma.$transaction(async (tx) => {
    await tx.user.update({
      data: {
        bannedAt: new Date(),
        bannedBy: byArg ?? null,
        bannedReason: reasonArg!,
      },
      where: { id: target.id },
    })

    // Flip the per-feature commandDisable setting so anything that gates
    // on it (bot chat reply path, dashboard banners) treats this user as
    // disabled. Mirrors what commandDisable.disable() does in shared-utils.
    await tx.setting.upsert({
      create: {
        autoDisabledAt: new Date(),
        autoDisabledBy: byArg ?? null,
        disableMetadata: { banned: true, reason: reasonArg! },
        disableReason: 'MANUAL_DISABLE',
        key: 'commandDisable',
        userId: target.id,
        value: true,
      },
      update: {
        autoDisabledAt: new Date(),
        autoDisabledBy: byArg ?? null,
        disableMetadata: { banned: true, reason: reasonArg! },
        disableReason: 'MANUAL_DISABLE',
        value: true,
      },
      where: { key_userId: { key: 'commandDisable', userId: target.id } },
    })

    // Drop the Twitch account row — fires the backend's DELETE:accounts
    // watcher → stopUserSubscriptions → eventSubMap cleanup + Twitch
    // EventSub conduit shard cleanup. The user can re-OAuth and create a
    // fresh row attached to the same users.id (allowDangerousEmailAccountLinking),
    // but the bannedAt on users survives that re-link and the jwt() gate
    // blocks login.
    await tx.account.deleteMany({ where: { userId: target.id } })

    // Note: NextAuth JWT strategy — no `sessions` table to delete from.
    // Live cookies remain valid until the user navigates to a page guarded
    // by requireDashboardAccess(), which now checks users.bannedAt and
    // redirects banned users to /error?error=ACCOUNT_BANNED.
  })

  console.log(`✅ Banned ${target.name} (${target.id}).`)
  console.log(
    'Backend watchers will tear down EventSub subscriptions + invalidate GSI tokens automatically.',
  )
}

function composite(foreground: Rgba, background: Rgba): Rgba {
  const alpha = foreground[3] + background[3] * (1 - foreground[3])
  return [
    (foreground[0] * foreground[3] + background[0] * background[3] * (1 - foreground[3])) / alpha,
    (foreground[1] * foreground[3] + background[1] * background[3] * (1 - foreground[3])) / alpha,
    (foreground[2] * foreground[3] + background[2] * background[3] * (1 - foreground[3])) / alpha,
    alpha,
  ]
}

async function processConfirmedNowPaymentsPayment(
  invoice: NowPaymentsInvoice,
  payment: NowPaymentsPaymentStatus,
): Promise<NowPaymentsProcessResult> {
  if (!isNowPaymentsConfirmed(payment.payment_status)) {
    return {
      processed: false,
      reason: 'not_confirmed',
      stripeInvoiceMarkedPaid: false,
      subscriptionCreated: false,
    }
  }

  const existingMetadata = getMetadata(invoice)

  if (
    invoice.lastWebhookAt &&
    invoice.status === payment.payment_status &&
    existingMetadata.processedSuccessfully === true
  ) {
    return {
      processed: false,
      reason: 'already_processed',
      stripeInvoiceMarkedPaid: false,
      subscriptionCreated: false,
    }
  }

  let stripeInvoiceMarkedPaid = false
  let subscriptionCreated = false

  try {
    let stripeInvoice = await stripe.invoices.retrieve(invoice.stripeInvoiceId)

    if (stripeInvoice.status !== 'paid') {
      stripeInvoice = await stripe.invoices.pay(
        invoice.stripeInvoiceId,
        { paid_out_of_band: true },
        { idempotencyKey: `nowpayments-${invoice.nowPaymentsId}` },
      )
      stripeInvoiceMarkedPaid = true
      console.log(
        `Marked Stripe invoice ${invoice.stripeInvoiceId} as paid via NOWPayments invoice ${invoice.nowPaymentsId}`,
      )
    }

    if (stripeInvoice.status !== 'paid') {
      stripeInvoice = await stripe.invoices.retrieve(invoice.stripeInvoiceId)
    }

    if (stripeInvoice.status !== 'paid') {
      throw new Error(
        `Stripe invoice ${invoice.stripeInvoiceId} is ${stripeInvoice.status ?? 'unknown'} after NOWPayments confirmation`,
      )
    }

    const handled = await prisma.$transaction(
      async (tx) => await handleInvoiceEvent(stripeInvoice, tx),
    )
    if (!handled) {
      throw new Error(`Invoice handler returned false for ${invoice.stripeInvoiceId}`)
    }

    subscriptionCreated = Boolean(
      await prisma.subscription.findFirst({
        orderBy: { createdAt: 'desc' },
        select: { id: true },
        where: {
          NOT: { status: 'CANCELED' },
          stripeCustomerId: invoice.stripeCustomerId,
          userId: invoice.userId,
        },
      }),
    )

    await prisma.nowPaymentsInvoice.update({
      data: {
        actuallyPaid: payment.actually_paid,
        lastWebhookAt: new Date(),
        metadata: {
          ...existingMetadata,
          invoiceId: invoice.stripeInvoiceId,
          nowPaymentsId: invoice.nowPaymentsId,
          paymentId: String(payment.payment_id),
          processedAt: new Date().toISOString(),
          processedSuccessfully: true,
          stripeInvoiceMarkedPaid,
          subscriptionCreated,
        },
        payAmount: payment.pay_amount,
        payCurrency: payment.pay_currency,
        paymentId: String(payment.payment_id),
        status: payment.payment_status,
      },
      where: { nowPaymentsId: invoice.nowPaymentsId },
    })

    return {
      processed: true,
      reason: 'processed',
      stripeInvoiceMarkedPaid,
      subscriptionCreated,
    }
  } catch (error) {
    await prisma.nowPaymentsInvoice.update({
      data: {
        metadata: {
          ...existingMetadata,
          errorStack: error instanceof Error ? error.stack : undefined,
          failedAt: new Date().toISOString(),
          invoiceId: invoice.stripeInvoiceId,
          lastError: error instanceof Error ? error.message : String(error),
          nowPaymentsId: invoice.nowPaymentsId,
          paymentId: String(payment.payment_id),
          processedSuccessfully: false,
          stripeInvoiceMarkedPaid,
          subscriptionCreated,
        },
      },
      where: { nowPaymentsId: invoice.nowPaymentsId },
    })

    throw error
  }
}

