async function handler(req: NextApiRequest, res: NextApiResponse) {
  try {
    const session = await getServerSession(req, res, authOptions)
    if (!session?.user?.id) {
      res.status(401).json({ message: 'Unauthorized' })
      return
    }

    const userId = session.user.id

    if (req.method === 'GET') {
      try {
        res.setHeader('Cache-Control', 'private, max-age=15, stale-while-revalidate=30')
        const includeRead = req.query.includeRead === 'true'

        const rows = await prisma.notification.findMany({
          include: {
            giftSubscription: true,
          },
          orderBy: {
            createdAt: 'desc',
          },
          where: {
            type: { in: ['GIFT_SUBSCRIPTION', 'NEW_FEATURE'] },
            userId,
            ...(includeRead ? {} : { isRead: false }),
          },
        })

        // Gift aggregate still surfaced here (consumed by the gift toast + admin page).
        const activeSubscriptions = await prisma.subscription.findMany({
          include: {
            giftDetails: true,
          },
          where: {
            status: 'ACTIVE',
            userId,
          },
        })
        const hasLifetime = activeSubscriptions.some(
          (sub) =>
            sub.giftDetails?.giftType === 'lifetime' ||
            (sub.tier === 'PRO' && sub.transactionType === 'LIFETIME'),
        )

        const notifications = rows
          .map((n) => {
            if (n.type === 'NEW_FEATURE') {
              return {
                createdAt: n.createdAt,
                id: n.id,
                read: n.isRead,
                type: 'NEW_FEATURE' as const,
              }
            }

            // GIFT_SUBSCRIPTION — drop orphaned rows whose gift was deleted.
            if (!n.giftSubscription) {
              return null
            }

            return {
              createdAt: n.createdAt,
              giftMessage: n.giftSubscription.giftMessage,
              giftQuantity: n.giftSubscription.giftQuantity || 1,
              giftType: n.giftSubscription.giftType,
              id: n.id,
              read: n.isRead,
              senderName: n.giftSubscription.senderName,
              type: 'GIFT_SUBSCRIPTION' as const,
            }
          })
          .filter(Boolean)

        res.status(200).json({
          hasLifetime,
          notifications,
          totalNotifications: notifications.length,
        })
        return
      } catch (error) {
        console.error('Error fetching notifications:', error)
        res.status(500).json({ error: String(error), message: 'Internal server error' })
        return
      }
    }

    if (req.method === 'POST') {
      try {
        const validationResult = markAsReadSchema.safeParse(req.body)
        if (!validationResult.success) {
          res
            .status(400)
            .json({ errors: validationResult.error.format(), message: 'Invalid request body' })
          return
        }

        const { notificationId } = validationResult.data

        // Scope the update to the caller's own notifications.
        const notification = await prisma.notification.findFirst({
          where: {
            id: notificationId,
            userId,
          },
        })

        if (!notification) {
          res.status(404).json({ message: 'Notification not found' })
          return
        }

        await prisma.notification.update({
          data: {
            isRead: true,
            updatedAt: new Date(),
          },
          where: {
            id: notificationId,
          },
        })

        res.status(200).json({ message: 'Notification marked as read' })
        return
      } catch (error) {
        console.error('Error marking notification as read:', error)
        res.status(500).json({ error: String(error), message: 'Internal server error' })
        return
      }
    }

    res.status(405).json({ message: 'Method not allowed' })
    return
  } catch (error) {
    console.error('Unexpected error in notifications API:', error)
    res.status(500).json({ error: String(error), message: 'Internal server error' })
    return
  }
}

async function processSubscriptionRefund(
  userId: string,
  charge: Stripe.Charge,
  tx: Prisma.TransactionClient,
): Promise<void> {
  // Get all active subscriptions for this user/customer
  const subscriptions = await tx.subscription.findMany({
    where: {
      stripeCustomerId: charge.customer as string,
      userId,
    },
  })

  if (subscriptions.length === 0) {
    const customerId =
      typeof charge.customer === 'string' ? charge.customer : (charge.customer?.id ?? 'null')
    console.log(`No subscriptions found for user ${userId} with customer ${customerId}`)
    return
  }

  // Log what we found
  console.log(`Found ${subscriptions.length} subscriptions to update for refund`)

  // Update each subscription based on the refund
  for (const subscription of subscriptions) {
    // For lifetime or one-time purchases, handle refunds by updating status
    if (subscription.transactionType === TransactionType.LIFETIME) {
      // If fully refunded, mark the purchase as canceled
      if (charge.refunded) {
        await tx.subscription.update({
          data: {
            metadata: {
              ...(subscription.metadata as Record<string, unknown>),
              refundAmount: charge.amount_refunded > 0 ? charge.amount_refunded.toString() : null,
              refundId: charge.refunds?.data?.[0]?.id || null,
              refundedAt: new Date().toISOString(),
            },
            status: SubscriptionStatus.CANCELED,
            updatedAt: new Date(),
          },
          where: { id: subscription.id },
        })
        console.log(
          `Marked ${subscription.transactionType} subscription ${subscription.id} as canceled due to full refund`,
        )
      }
      // If partially refunded, update the metadata
      else if (charge.amount_refunded > 0) {
        await tx.subscription.update({
          data: {
            metadata: {
              ...(subscription.metadata as Record<string, unknown>),
              partiallyRefundedAt: new Date().toISOString(),
              refundAmount: charge.amount_refunded.toString(),
              refundId: charge.refunds?.data?.[0]?.id || null,
            },
            updatedAt: new Date(),
          },
          where: { id: subscription.id },
        })
        console.log(
          `Updated ${subscription.transactionType} subscription ${subscription.id} metadata for partial refund`,
        )
      }
    }
    // For crypto payments, we need to manually cancel them since Stripe won't handle it through subscription webhooks
    else if (
      (subscription.metadata as Record<string, unknown>)?.isCryptoPayment === 'true' &&
      charge.refunded
    ) {
      await tx.subscription.update({
        data: {
          metadata: {
            ...(subscription.metadata as Record<string, unknown>),
            fullyRefunded: 'true',
            refundAmount: charge.amount_refunded > 0 ? charge.amount_refunded.toString() : null,
            refundId: charge.refunds?.data?.[0]?.id || null,
            refundedAt: new Date().toISOString(),
          },
          status: SubscriptionStatus.CANCELED,
          updatedAt: new Date(),
        },
        where: { id: subscription.id },
      })
      console.log(`Manually canceled crypto subscription ${subscription.id} due to refund`)
    }
    // For recurring subscriptions, just record the refund in metadata
    // The actual subscription status changes will come from Stripe subscription webhooks
    else if (subscription.status !== SubscriptionStatus.CANCELED) {
      await tx.subscription.update({
        data: {
          metadata: {
            ...(subscription.metadata as Record<string, unknown>),
            fullyRefunded: charge.refunded ? 'true' : 'false',
            refundAmount: charge.amount_refunded > 0 ? charge.amount_refunded.toString() : null,
            refundId: charge.refunds?.data?.[0]?.id || null,
            refundRecorded: new Date().toISOString(),
          },
          updatedAt: new Date(),
        },
        where: { id: subscription.id },
      })
      console.log(`Updated recurring subscription ${subscription.id} metadata for refund`)
    }
  }
}

function mapStripeStatus(status: string): SubscriptionStatus {
  switch (status) {
    case 'active': {
      return SubscriptionStatus.ACTIVE
    }
    case 'trialing': {
      return SubscriptionStatus.TRIALING
    }
    case 'past_due': {
      return SubscriptionStatus.PAST_DUE
    }
    case 'canceled': {
      return SubscriptionStatus.CANCELED
    }
    case 'unpaid': {
      return SubscriptionStatus.PAST_DUE
    }
    case 'incomplete': {
      return SubscriptionStatus.PAST_DUE
    }
    case 'incomplete_expired': {
      return SubscriptionStatus.CANCELED
    }
    default: {
      return SubscriptionStatus.CANCELED
    }
  }
}

