'antd', async () => {
  const { Children, cloneElement, isValidElement } = await import('react')

  const Button = ({
    children,
    disabled,
    loading,
    type: _type,
    ...props
  }: ComponentProps<'button'> & { loading?: boolean }) => (
    <button {...props} disabled={disabled || loading}>
      {children}
    </button>
  )

  const FormItem = ({
    children,
    colon: _colon,
    label,
    ...props
  }: {
    children: ReactNode
    colon?: boolean
    label?: ReactNode
  } & ComponentProps<'div'>) => (
    <div {...props}>
      {label && <span>{label}</span>}
      {children}
    </div>
  )

  const Form = Object.assign(
    ({ children, layout: _layout }: { children: ReactNode; layout?: string }) => (
      <form>{children}</form>
    ),
    { Item: FormItem },
  )

  const Input = (props: ComponentProps<'input'>) => <input {...props} />

  const InputNumber = ({
    onChange,
    precision: _precision,
    value,
    ...props
  }: Omit<ComponentProps<'input'>, 'onChange' | 'value'> & {
    onChange?: (value: number | null) => void
    precision?: number
    value?: number | null
  }) => (
    <input
      {...props}
      type='number'
      value={value ?? ''}
      onChange={(event) => {
        onChange?.(event.currentTarget.value === '' ? null : Number(event.currentTarget.value))
      }}
    />
  )

  type RadioButtonProps = {
    checked?: boolean
    children: ReactNode
    disabled?: boolean
    onChange?: (event: { target: { value: number } }) => void
    value?: number
  }

  const RadioButton = ({ children, checked, disabled, onChange, value }: RadioButtonProps) => (
    <label>
      <input
        checked={checked}
        disabled={disabled}
        type='radio'
        value={value}
        onChange={() => {
          onChange?.({ target: { value: value ?? 0 } })
        }}
      />
      {children}
    </label>
  )

  const RadioGroup = ({
    'aria-label': ariaLabel,
    children,
    disabled,
    onChange,
    value,
  }: {
    'aria-label'?: string
    children: ReactNode
    disabled?: boolean
    onChange?: (event: { target: { value: number } }) => void
    value?: number
  }) => (
    <div aria-label={ariaLabel} role='radiogroup'>
      {Children.map(children, (child) => {
        if (!isValidElement<RadioButtonProps>(child)) {
          return child
        }

        return cloneElement(child, {
          checked: child.props.value === value,
          disabled: disabled || child.props.disabled,
          onChange,
        })
      })}
    </div>
  )

  const SkeletonInput = ({ style }: { style?: CSSProperties }) => (
    <div aria-busy='true' style={style} />
  )

  return {
    Button,
    Form,
    Input,
    InputNumber,
    Radio: { Button: RadioButton, Group: RadioGroup },
    Skeleton: { Input: SkeletonInput },
  }
}

