function useLastFm() {
  const [track, setTrack] = useState<LastFmTrackType | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const prevTrackRef = useRef<LastFmTrackType | null>(null)

  const { data: isEnabled } = useUpdateSetting(Settings.lastFmOverlay)
  const { data: username } = useUpdateSetting<string>(Settings.lastFmUsername)
  const { data: refreshRate } = useUpdateSetting(Settings.lastFmRefreshRate)

  const fetchNowPlaying = useCallback(async () => {
    if (!username || !LASTFM_API_KEY) {
      return
    }

    try {
      setLoading(true)
      setError(null)

      // Call Last.fm via the Next.js rewrite proxy — no serverless function invocation
      const url = `/lastfm-proxy/2.0/?method=user.getrecenttracks&user=${encodeURIComponent(username)}&api_key=${LASTFM_API_KEY}&format=json&limit=1`
      const response = await fetch(url)

      if (!response.ok) {
        setError('Error fetching Last.fm data')
        setTrack(null)
        return
      }

      const data = await response.json()
      const parsed = parseLastFmResponse(data)

      if (!parsed) {
        setError(data?.message || 'Not currently playing anything')
        setTrack(null)
        return
      }

      // Compare with previous track to avoid unnecessary rerenders
      const prev = prevTrackRef.current
      if (
        !prev ||
        prev.artist !== parsed.artist ||
        prev.title !== parsed.title ||
        prev.album !== parsed.album ||
        prev.albumArt !== parsed.albumArt ||
        prev.url !== parsed.url
      ) {
        prevTrackRef.current = parsed
        setTrack(parsed)
      }
    } catch (error) {
      console.error('Error fetching Last.fm data:', error)
      setError('Failed to fetch Last.fm data')
      setTrack(null)
    } finally {
      setLoading(false)
    }
  }, [username])

  useEffect(() => {
    if (!isEnabled || !username) {
      return
    }

    // Initial fetch
    void fetchNowPlaying()

    // Set up interval to fetch periodically
    const configuredInterval = typeof refreshRate === 'number' ? refreshRate : 30
    const intervalSeconds = Math.max(30, configuredInterval)
    const intervalId = setInterval(fetchNowPlaying, intervalSeconds * 1000)

    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        void fetchNowPlaying()
      }
    }
    document.addEventListener('visibilitychange', handleVisibilityChange)

    return () => {
      clearInterval(intervalId)
      document.removeEventListener('visibilitychange', handleVisibilityChange)
    }
  }, [isEnabled, username, refreshRate, fetchNowPlaying])

  return { error, loading, track }
}

function useWinLoss({ statsDays, statsStartDate, twitchId, userId }: UseWinLossOptions) {
  const [connected, setConnected] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const [wl, setWL] = useState<WLData | null>(null)
  const socketRef = useRef<Socket | null>(null)
  const statsDaysRef = useRef(statsDays)
  const statsStartDateRef = useRef(statsStartDate)
  const lastRequestedWindowRef = useRef<string | null>(null)
  const requestIdRef = useRef(0)
  const requestCurrentWLRef = useRef<((force?: boolean) => void) | null>(null)
  const isPreview = userId != null

  statsDaysRef.current = statsDays
  statsStartDateRef.current = statsStartDate

  useEffect(() => {
    const identifier = isPreview ? userId : twitchId
    if (!identifier) {
      setLoading(false)
      return
    }

    const socket = io(process.env.NEXT_PUBLIC_GSI_WEBSOCKET_URL, {
      auth: isPreview
        ? { client: 'win-loss', token: identifier }
        : { client: 'profile-wl', twitchId: identifier },
      reconnection: true,
      reconnectionAttempts: Number.POSITIVE_INFINITY,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
      timeout: 20_000,
    })
    socketRef.current = socket

    const requestCurrentWL = (force = false) => {
      const currentStatsDays = statsDaysRef.current
      const currentStatsStartDate = statsStartDateRef.current
      const requestKey =
        currentStatsDays === undefined && currentStatsStartDate === undefined
          ? 'configured'
          : `${String(currentStatsDays)}:${String(currentStatsStartDate)}`
      if (!force && lastRequestedWindowRef.current === requestKey) {
        return
      }

      lastRequestedWindowRef.current = requestKey
      const requestId = ++requestIdRef.current
      socket.emit(
        'request-wl',
        currentStatsDays === undefined && currentStatsStartDate === undefined
          ? {}
          : { statsDays: currentStatsDays, statsStartDate: currentStatsStartDate },
        (response: WinLossResponse) => {
          if (requestId !== requestIdRef.current) {
            return
          }
          setLoading(false)
          if (!isWinLossData(response)) {
            setError(response.error)
            return
          }
          setError(null)
          setWL(response)
        },
      )
    }
    requestCurrentWLRef.current = requestCurrentWL

    const handleConnect = () => {
      setConnected(true)
      requestCurrentWL(true)
    }
    const handleDisconnect = () => {
      setConnected(false)
    }
    const handleUpdate = (
      records: WLRecord[],
      updatedStatsDays: number | null = null,
      statsDaysTotal: number | null = null,
    ) => {
      if (isPreview) {
        requestCurrentWL(true)
        return
      }
      requestIdRef.current += 1
      setWL({ records, statsDays: updatedStatsDays, statsDaysTotal })
      setLoading(false)
    }

    socket.on('connect', handleConnect)
    socket.on('disconnect', handleDisconnect)
    socket.on('connect_error', handleDisconnect)
    socket.on('update-wl', handleUpdate)

    if (socket.connected) {
      handleConnect()
    }

    return () => {
      socket.off('connect', handleConnect)
      socket.off('disconnect', handleDisconnect)
      socket.off('connect_error', handleDisconnect)
      socket.off('update-wl', handleUpdate)
      socket.disconnect()
      requestIdRef.current += 1
      socketRef.current = null
      requestCurrentWLRef.current = null
      lastRequestedWindowRef.current = null
    }
  }, [isPreview, twitchId, userId])

  useEffect(() => {
    if (!isPreview || !socketRef.current?.connected) {
      return
    }

    const requestKey =
      statsDays === undefined && statsStartDate === undefined
        ? 'configured'
        : `${String(statsDays)}:${String(statsStartDate)}`
    if (lastRequestedWindowRef.current === requestKey) {
      return
    }

    lastRequestedWindowRef.current = requestKey
    const requestId = ++requestIdRef.current
    setLoading(true)
    socketRef.current.emit(
      'request-wl',
      statsDays === undefined && statsStartDate === undefined ? {} : { statsDays, statsStartDate },
      (response: WinLossResponse) => {
        if (requestId !== requestIdRef.current) {
          return
        }
        setLoading(false)
        if (!isWinLossData(response)) {
          setError(response.error)
          return
        }
        setError(null)
        setWL(response)
      },
    )
  }, [isPreview, statsDays, statsStartDate])

  const refresh = useCallback(() => requestCurrentWLRef.current?.(true), [])

  return { connected, error, loading, refresh, wl }
}

