async function createCryptoInvoice(
  params: Omit<CheckoutSessionParams, 'isGift' | 'isCryptoPayment' | 'isPaypalPayment'>,
): Promise<string> {
  const {
    customerId,
    priceId,
    isRecurring,
    isLifetime,
    subscriptionData,
    userId,
    email,
    name,
    image,
    locale,
    twitchId,
  } = params

  // Cancel any pending crypto invoices if this is an upgrade
  if (subscriptionData?.stripePriceId) {
    try {
      const existingSubscription = await prisma.subscription.findFirst({
        select: { metadata: true },
        where: {
          NOT: { status: 'CANCELED' },
          stripeCustomerId: customerId,
          userId,
        },
      })

      const metadata = (existingSubscription?.metadata as Record<string, unknown>) || {}
      const renewalInvoiceId = metadata.renewalInvoiceId as string

      if (renewalInvoiceId) {
        console.log(`Canceling pending invoice ${renewalInvoiceId} for user ${userId}`)
        try {
          await stripe.invoices.voidInvoice(renewalInvoiceId)
        } catch {
          try {
            const invoice = await stripe.invoices.retrieve(renewalInvoiceId)
            if (invoice.status === 'open') {
              await stripe.invoices.markUncollectible(renewalInvoiceId)
            }
          } catch (markError) {
            console.error(`Failed to handle invoice ${renewalInvoiceId}:`, markError)
          }
        }
      }
    } catch (error) {
      console.error('Error canceling pending invoices:', error)
    }
  }

  const { getCurrentPeriod } = await import('@/utils/subscription')
  const pricePeriod = getCurrentPeriod(priceId)
  const price = await stripe.prices.retrieve(priceId)

  if (!price.unit_amount) {
    throw new Error('Price has no unit amount')
  }

  const dueDate = new Date()
  dueDate.setDate(dueDate.getDate() + 7)

  const invoiceParams: Stripe.InvoiceCreateParams = {
    collection_method: 'send_invoice',
    customer: customerId,
    due_date: Math.floor(dueDate.getTime() / 1000),
    metadata: {
      email,
      image,
      isCryptoPayment: 'true',
      isNewSubscription: isRecurring && !subscriptionData?.stripeSubscriptionId ? 'true' : 'false',
      isUpgradeToLifetime: isLifetime && subscriptionData?.stripeSubscriptionId ? 'true' : 'false',
      locale,
      name,
      paymentProvider: 'nowpayments',
      previousSubscriptionId: subscriptionData?.stripeSubscriptionId ?? '',
      pricePeriod,
      stripePriceId: priceId,
      twitchId,
      userId,
    },
    payment_settings: {
      payment_method_types: [],
    },
  }

  const stripeInvoice = await stripe.invoices.create(invoiceParams)
  if (!stripeInvoice?.id) {
    throw new Error('Stripe invoice creation failed')
  }

  await stripe.invoiceItems.create({
    customer: customerId,
    invoice: stripeInvoice.id,
    price_data: {
      currency: price.currency,
      product: price.product as string,
      unit_amount: price.unit_amount,
    },
  })

  const finalized = await stripe.invoices.finalizeInvoice(stripeInvoice.id, {
    auto_advance: false,
  })

  const { url, nowPaymentsId } = await createAndStoreCryptoInvoice({
    metadata: { pricePeriod, stripePriceId: priceId },
    orderDescription: `Dotabod ${pricePeriod} subscription`,
    stripeInvoice: finalized,
    userId,
  })

  await stripe.invoices.update(stripeInvoice.id, {
    metadata: {
      ...invoiceParams.metadata,
      nowpayments_invoice_id: nowPaymentsId,
      nowpayments_invoice_url: url,
    },
  })

  return url
}

function WidgetPage() {
  const { mutate } = useUpdateSetting(Settings.commandWL)
  const router = useRouter()
  const { userId } = router.query
  const { original } = useUpdateSetting()
  const res = useTransformRes()
  const { wlPosition } = useOverlayPositions()
  const { data: isRight } = useUpdateSetting(Settings.minimapRight)
  const [wl, setWL] = useState<wlType>({
    records: [{ lose: 0, type: 'U', win: 0 }],
    statsDays: null,
  })
  const [rankImageDetails, setRankImageDetails] = useState<{
    image: string | null
    rank: number | null
    leaderboard: number | null | undefined
    notLoaded?: boolean
  }>({
    image: '0.png',
    leaderboard: 0,
    notLoaded: true,
    rank: 0,
  })

  useEffect(() => {
    if (isMaintenanceMode) {
      return
    }
    if (!userId) {
      return
    }

    console.log('Connecting to socket init...')

    socket = io(process.env.NEXT_PUBLIC_GSI_WEBSOCKET_URL, {
      auth: { token: userId },
    })

    socket.on(
      'update-wl',
      (
        records: WLRecord[],
        statsDays: number | null = null,
        statsDaysTotal: number | null = null,
      ) => {
        if (isDev()) {
          return
        }
        setWL({ records, statsDays, statsDaysTotal })
      },
    )

    socket.on('refresh-settings', () => {
      mutate()
    })

    socket.on('update-medal', (deets: RankType) => {
      if (isDev()) {
        return
      }
      const rankDetails = getRankImage(deets)
      setRankImageDetails({
        image: rankDetails.image,
        leaderboard: rankDetails.leaderboard,
        notLoaded: false,
        rank: rankDetails.rank,
      })
    })
  }, [userId])

  useEffect(() => {
    if (isMaintenanceMode) {
      return
    }

    return () => {
      socket?.off('update-wl')
      socket?.off('refresh-settings')
      socket?.off('update-medal')
    }
  }, [])

  useEffect(() => {
    if (isMaintenanceMode) {
      return
    }
    if (!original) {
      return
    }

    const steamAccount = original.SteamAccount?.[0]
    const rank = getRankDetail(
      Number(steamAccount?.mmr ?? original.mmr ?? 0),
      steamAccount?.leaderboard_rank ?? null,
    )

    if (!rank) {
      return
    }

    const leaderboard =
      'standing' in rank ? rank.standing : (steamAccount?.leaderboard_rank ?? null)

    const rankDetails: {
      image: string
      rank: number
      leaderboard: number | null
      notLoaded: boolean
    } = {
      image: rank.myRank?.image ?? '0.png',
      leaderboard,
      notLoaded: false,
      rank: rank.mmr,
    }

    setRankImageDetails(rankDetails)
  }, [original])

  if (isMaintenanceMode) {
    return null
  }

  return (
    <div>
      <div
        className={clsx('absolute flex items-end justify-end', isRight && 'justify-start!')}
        id='ingame-wl-mmr-card'
        style={{
          ...wlPosition,
          left: wlPosition.left ?? undefined,
          width: res({ w: 215 }),
        }}
      >
        <RestrictFeature feature='commandWL'>
          <AnimatedWL
            key='animate-wl-class'
            wl={wl}
            className={clsx('block', isRight && 'order-2')}
          />
        </RestrictFeature>

        <RestrictFeature feature='showRankImage'>
          <AnimatedRankBadge
            className={clsx('block', isRight && 'order-1')}
            key='animate-rank-badge-class'
            rankImageDetails={{
              ...rankImageDetails,
              leaderboard: rankImageDetails.leaderboard ?? null,
            }}
          />
        </RestrictFeature>
      </div>
    </div>
  )
}

