async function reconcileTwitchProfile({
  prisma,
  userId,
  accessToken,
  currentName,
  currentDisplayName,
}: ReconcileArgs): Promise<ReconcileResult> {
  const helix = await fetchHelix(accessToken)
  if (!helix) {
    return 'helix-unavailable'
  }

  if (currentName === helix.login && currentDisplayName === helix.display_name) {
    return 'no-change'
  }

  await prisma.user.update({
    data: {
      displayName: helix.display_name,
      name: helix.login,
      updatedAt: new Date(),
    },
    where: { id: userId },
  })
  return 'updated'
}

function computeFallbackPeriodEnd(priceType: string): Date {
  const end = new Date()
  if (priceType === 'annual') {
    end.setFullYear(end.getFullYear() + 1)
  } else {
    end.setMonth(end.getMonth() + 1)
  }
  return end
}

