function getRankDetail(mmr: string | number, standing: number | null) {
  const mmrNum = Number(mmr)

  if (!mmrNum || mmrNum < 0) {
    return null
  }

  // Higher than max mmr? Lets check leaderboards
  const maxRank = ranks.at(-1)
  if (maxRank && mmrNum > maxRank.range[1]) {
    return lookupLeaderRank({ mmr: mmrNum, standing })
  }

  const [myRank, nextRank] = ranks.filter((rank) => mmrNum <= rank.range[1])

  // Its not always truthy, nextRank can be beyond the range
  const nextMMR = nextRank?.range[0] || myRank?.range[1]
  const mmrToNextRank = nextMMR - mmrNum
  const winsToNextRank = Math.ceil(mmrToNextRank / 30)

  return {
    mmr: mmrNum,
    mmrToNextRank,
    myRank,
    nextMMR,
    nextRank,
    winsToNextRank,
  }
}

function calculateSavings(monthlyPrice: string, annualPrice: string): number {
  const monthly = Number.parseFloat(monthlyPrice.replace('$', '')) * 12
  const annual = Number.parseFloat(annualPrice.replace('$', ''))
  return Math.round(((monthly - annual) / monthly) * 100)
}

function serializeData(data: unknown): JsonValue {
  if (data === null || data === undefined) {
    return null
  }

  if (data instanceof Date) {
    return data.toISOString()
  }

  if (typeof data === 'bigint') {
    return data.toString()
  }

  if (Array.isArray(data)) {
    return data.map(serializeData)
  }

  if (typeof data === 'object') {
    return Object.fromEntries(
      Object.entries(data as Record<string, unknown>).map(([key, value]) => [
        key,
        serializeData(value),
      ]),
    )
  }

  if (typeof data === 'string' || typeof data === 'number' || typeof data === 'boolean') {
    return data
  }

  return null
}

