            enabled: true,
            maximum: 100,
            minimum: 1,
          },
        }

function verifyPaylinkToken(invoiceId: string, token: string): PaylinkToken | null {
  const [signature, expStr] = (token || '').split('.')

  if (!signature || !expStr) {
    return null
  }

  const expiresAt = Number(expStr)
  if (!expiresAt || Date.now() > expiresAt) {
    return null
  }

  const payload = `${invoiceId}|${expStr}`
  const secret = process.env.PAYLINK_SIGNING_SECRET
  if (!secret) {
    return null
  }
  const expectedSignature = crypto.createHmac('sha256', secret).update(payload).digest('base64url')

  if (!crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSignature))) {
    return null
  }

  return { expiresAt, invoiceId }
}

async function getMatchData(matchId: string, heroId: number) {
  // Check if we already have this match data cached
  if (matchDataCache.has(matchId)) {
    console.log(`[MMR] Using cached match data for matchId: ${matchId}`)
    return matchDataCache.get(matchId)
  }

  try {
    const opendotaMatch = await axios(`https://api.opendota.com/api/matches/${matchId}`)

    // If the match data is incomplete, we might need to request parsing
    if (!opendotaMatch.data?.players) {
      console.log(`[MMR] Match ${matchId} data incomplete, attempting to request parsing`)
      try {
        const jobId = await createJob(matchId)
        await getJobStatus(jobId)
        // After job completes, try fetching the match data again
        return getMatchData(matchId, heroId)
      } catch (error) {
        console.error(`[MMR] Failed to parse match ${matchId}:`, error)
        throw new Error(`Match ${matchId} not available or not ready to be parsed`, {
          cause: error,
        })
      }
    }

    let radiantWin = null
    let lobbyType = null
    const moreData = {
      assists: 0,
      deaths: 0,
      direScore: 0,
      kills: 0,
      radiantScore: 0,
    }

    if (Array.isArray(opendotaMatch.data?.players)) {
      if (typeof opendotaMatch?.data?.radiant_win === 'boolean') {
        radiantWin = opendotaMatch?.data?.radiant_win
        moreData.radiantScore = opendotaMatch?.data?.radiant_score || 0
        moreData.direScore = opendotaMatch?.data?.dire_score || 0
      }

      // Extract player-specific stats if heroId is provided
      if (heroId) {
        const player = opendotaMatch.data.players.find(
          (p: { hero_id: number }) => p.hero_id === heroId,
        )
        if (player) {
          moreData.kills = player.kills || 0
          moreData.deaths = player.deaths || 0
          moreData.assists = player.assists || 0
        }
      }

      if (typeof opendotaMatch?.data?.lobby_type === 'number') {
        lobbyType = opendotaMatch?.data?.lobby_type
      }
    } else {
      throw new TypeError('Match data is incomplete')
    }

    const result = {
      lobbyType,
      matchId,
      radiantWin,
      ...moreData,
    }

    // Cache the result
    matchDataCache.set(matchId, result)

    return result
  } catch (error) {
    console.error(`[MMR] Error fetching match ${matchId}:`, error)
    throw new Error(`Failed to fetch match data for ${matchId}`, { cause: error })
  }
}

async function syncPaypalSubscription(paypalSubscriptionId: string): Promise<boolean> {
  const record = await prisma.payPalSubscription.findUnique({
    where: { paypalSubscriptionId },
  })
  if (!record) {
    console.warn(`No PayPalSubscription row for ${paypalSubscriptionId}`)
    return false
  }

  const details = await getSubscription(paypalSubscriptionId)
  const { userId } = record
  const metadata = (record.metadata as Record<string, unknown>) || {}
  const priceType = (metadata.priceType as string) || 'monthly'
  const stripePriceId = (metadata.stripePriceId as string) || null
  const status = mapStatus(details.status)
  const stripeSubscriptionId = `paypal_${paypalSubscriptionId}`

  const currentPeriodEnd = details.nextBillingTime
    ? new Date(details.nextBillingTime)
    : computeFallbackPeriodEnd(priceType)

  await prisma.$transaction(async (tx) => {
    await tx.payPalSubscription.update({
      data: {
        lastWebhookAt: new Date(),
        payerId: details.payerId ?? record.payerId,
        status: details.status,
      },
      where: { paypalSubscriptionId },
    })

    await tx.subscription.upsert({
      create: {
        cancelAtPeriodEnd: false,
        currentPeriodEnd,
        metadata: {
          paymentProvider: 'paypal',
          paypalSubscriptionId,
          priceType,
        },
        status,
        stripePriceId,
        stripeSubscriptionId,
        tier: 'PRO',
        transactionType: TransactionType.RECURRING,
        userId,
      },
      update: {
        currentPeriodEnd,
        metadata: {
          paymentProvider: 'paypal',
          paypalSubscriptionId,
          priceType,
        },
        status,
        stripePriceId,
        updatedAt: new Date(),
      },
      where: { stripeSubscriptionId },
    })
  })

  return true
}

